CardSets.register({"id":"houseplants","name":"Houseplants","code":"POTTED","description":"372 cards celebrating the plants that share our homes — monsteras and philodendrons, hoyas and prayer plants, ferns, palms, orchids and succulents, plus the care, propagation and pest lore of indoor gardening.","theme":{"primary":"#4e7a3a","secondary":"#2e4a2f","artBackground":"#eef3e4","artFit":"cover"},"pack":{"name":"Houseplants Pack","emblem":"🪴","skin":"houseplants","slots":[{"count":5,"label":"Common","odds":{"common":100}},{"count":2,"label":"Uncommon","odds":{"uncommon":100}},{"count":1,"label":"Wild card","odds":{"common":55,"uncommon":30,"rare":12,"epic":3}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":81.8,"epic":14,"legendary":4,"chase":0.2}}]},"cards":[{"name":"Monstera deliciosa","rarity":"chase","id":"monstera-deliciosa","subtitle":"Aroid","details":"The Swiss cheese plant: huge split, hole-punched leaves made it the defining houseplant of the modern indoor jungle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20deliciosa%20DSC02605.jpg?width=1024"},{"name":"Monstera deliciosa 'Albo Variegata'","rarity":"chase","id":"monstera-deliciosa-albo-variegata","subtitle":"Cultivar","details":"White-splashed Monstera whose marbled leaves turned it into the most famous collector plant of the houseplant boom.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fruit%20Salad%20Plant%20%28Monstera%20deliciosa%20%27Albo-Variegata%27%29.jpg?width=1024"},{"name":"Philodendron 'Pink Princess'","rarity":"chase","id":"philodendron-pink-princess","subtitle":"Cultivar","details":"Near-black leaves splashed with bubblegum pink; the variegated Philodendron that launched a thousand wish lists.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pink%20princess%20philodendron.jpg?width=1024"},{"name":"Golden Pothos","rarity":"chase","id":"golden-pothos","subtitle":"Aroid","details":"The near-indestructible trailing vine on countless shelves; its gold-splashed leaves root from a cutting in plain water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Epipremnum%20aureum%20%28Golden%20pothos%29.jpg?width=1024"},{"name":"ZZ Plant","rarity":"chase","id":"zz-plant","subtitle":"Aroid","details":"Glossy leaflets rise from thick rhizomes that store water for months; the low-light office survivor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zamioculcas%20zamiifolia%201.jpg?width=1024"},{"name":"String of Pearls","rarity":"chase","id":"string-of-pearls","subtitle":"Trailer","details":"A cascade of pea-green beads on wiry stems; each sphere is a water-storing leaf with a tiny translucent window stripe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curio%20rowleyanus%20syn.%20Senecio%20rowleyanus%202019-04-14%2002.jpg?width=1024"},{"name":"Venus Flytrap","rarity":"chase","id":"venus-flytrap","subtitle":"Carnivorous","details":"Hinged leaves snap shut in a tenth of a second when trigger hairs are touched twice, sealing the insect inside for digestion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Venus%20Flytrap%20showing%20trigger%20hairs.jpg?width=1024"},{"name":"Snake Plant","rarity":"chase","id":"snake-plant","subtitle":"Succulent","details":"Upright sword leaves edged in gold; thrives on neglect, low light, and the driest soil on the windowsill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dracaena%20trifasciata%20%27Laurentii%27%20-%20Begonia%20House%20-%20Wellington%20Botanic%20Garden%20-%20Wellington%2C%20NZ%20-%20DSC09390.jpg?width=1024"},{"name":"Fiddle-Leaf Fig","rarity":"chase","id":"fiddle-leaf-fig","subtitle":"Tree","details":"Ficus lyrata's huge violin-shaped leaves made it the defining statement tree of the modern indoor jungle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ficus%20lyrata-Jardin%20botanique%20Jean-Marie%20Pelt%20%281%29.jpg?width=900"},{"name":"Spider Plant","rarity":"chase","id":"spider-plant","subtitle":"Foliage","details":"Chlorophytum comosum dangles baby plantlets on long stems and shrugs off neglect like almost no other houseplant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chlorophytum%20comosum%20%28%20spider%20grass%29.jpg?width=1024"},{"name":"Monstera deliciosa 'Thai Constellation'","rarity":"legendary","id":"monstera-deliciosa-thai-constellation","subtitle":"Cultivar","details":"Lab-born Monstera freckled with stable cream speckles like a night sky; named for the Thai lab that created it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/201016%20117%20San%20Diego%20Botanic%20Garden%20-%20Dickinson%20Family%20Conseratory%2C%20Monstera%20deliciosa%20%27Thai%20Constellation%27%20Variegated%20Mexican%20Breadfruit%2C%20Aglaomorpha%20coronans%20Santa%20Rosa%20Fern.jpg?width=900"},{"name":"Monstera adansonii","rarity":"legendary","id":"monstera-adansonii","subtitle":"Aroid","details":"The Swiss cheese vine: a trailing climber whose oval leaves are punched with neat rows of natural holes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20adansonii%20202003.jpg?width=1024"},{"name":"Philodendron gloriosum","rarity":"legendary","id":"philodendron-gloriosum","subtitle":"Aroid","details":"Velvet, heart-shaped leaves with glowing white veins; it creeps along the soil instead of climbing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20gloriosum.jpg?width=1024"},{"name":"Philodendron 'White Princess'","rarity":"legendary","id":"philodendron-white-princess","subtitle":"Cultivar","details":"Glossy green leaves streaked with white variegation on pink-edged stems; hints of pink appear in strong light.","image":"https://planteia.ca/cdn/shop/files/white-princess-leaf.jpg?v=1717775201&width=1200"},{"name":"Philodendron melanochrysum","rarity":"legendary","id":"philodendron-melanochrysum","subtitle":"Aroid","details":"The black-gold Philodendron: long velvet leaves dusted gold, growing dramatically larger up a moss pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20melanochrysum%200zz.jpg?width=1024"},{"name":"Alocasia 'Polly'","rarity":"legendary","id":"alocasia-polly","subtitle":"Cultivar","details":"African-mask leaves: dark, glossy blades with pale veins and wavy edges, bred from Alocasia amazonica.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alocasia%20x%20amazonica%20%27Polly%27.jpg?width=1024"},{"name":"Anthurium clarinervium","rarity":"legendary","id":"anthurium-clarinervium","subtitle":"Aroid","details":"Heart-shaped velvet leaves veined in white; a Mexican species that became a collector's cornerstone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthurium%20clarinervium%20-%20Conservatory%20of%20Flowers%20-%20San%20Francisco%2C%20CA%20-%20DSC03116.JPG?width=900"},{"name":"Scindapsus pictus 'Exotica'","rarity":"legendary","id":"scindapsus-pictus-exotica","subtitle":"Cultivar","details":"Large satin leaves splashed with silver; a trailing pothos relative that shimmers in bright shade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scindapsus%20pictus%203358.jpg?width=900"},{"name":"Aglaonema pictum 'Tricolor'","rarity":"legendary","id":"aglaonema-pictum-tricolor","subtitle":"Cultivar","details":"Camouflage leaves in three shades of green; a slow Indonesian rarity prized like a living jewel.","image":"https://botanically.nl/wp-content/uploads/2020/11/aglaonema-pictum-tricolor.jpg"},{"name":"Calathea orbifolia","rarity":"legendary","id":"calathea-orbifolia","subtitle":"Prayer Plant","details":"Broad oval leaves banded in silver-green stripes; famously particular about water, light, and drafts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calathea%20orbifolia%20kz1.jpg?width=1024"},{"name":"Hoya carnosa 'Krimson Queen'","rarity":"legendary","id":"hoya-carnosa-krimson-queen","subtitle":"Cultivar","details":"The variegated wax plant: cream-and-pink edged leaves on a climbing heirloom hoya famous for porcelain star flowers.","image":"https://foliage-factory.com/cdn/shop/files/hoya-carnosa-krimson-queen-09.webp?v=1776360696&width=1200"},{"name":"String of Hearts","rarity":"legendary","id":"string-of-hearts","subtitle":"Trailer","details":"Silver-marbled heart leaves dangle on thread-thin purple stems that can trail for metres from a hanging pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ceropegia%20woodii%20Ceropegia%20Wooda%202024-04-26%2002.jpg?width=1024"},{"name":"Hoya kerrii","rarity":"legendary","id":"hoya-kerrii","subtitle":"Hoya","details":"The sweetheart hoya, sold as a single rooted heart leaf; a lucky Valentine's gift that can vine for years.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b2/Hoya-kerrii_flowers_op.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Peperomia 'Napoli Nights'","rarity":"legendary","id":"peperomia-napoli-nights","subtitle":"Cultivar","details":"A jewel-box peperomia: near-black rippled leaves with silver sparkle above and deep burgundy undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia%20albovittata%20%27Napoli%20Night%27%20kz01.jpg?width=1024"},{"name":"Phalaenopsis Orchid","rarity":"legendary","id":"phalaenopsis-orchid","subtitle":"Orchid","details":"The moth orchid: arching stems of moth-like blooms that can flower for months, the world's best-selling potted orchid.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phalaenopsis%20Orchid%20Flower.jpg?width=1024"},{"name":"Staghorn Fern","rarity":"legendary","id":"staghorn-fern","subtitle":"Fern","details":"Grown mounted on boards, it makes two frond types: flat shields that grip the mount and forked, antler-like fertile fronds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Platycerium%20bifurcatum%20kz01.jpg?width=1024"},{"name":"Bird's Nest Fern","rarity":"legendary","id":"birds-nest-fern","subtitle":"Fern","details":"Glossy, undivided fronds unfurl from a central rosette like eggs in a nest; it grows on trees and rocks in the wild.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asplenium%20nidus%20Bird%27s%20Nest%20Fern%20%E1%83%90%E1%83%A1%E1%83%9E%E1%83%9A%E1%83%94%E1%83%9C%E1%83%98%E1%83%A3%E1%83%9B%E1%83%98.JPG?width=1024"},{"name":"Majesty Palm","rarity":"legendary","id":"majesty-palm","subtitle":"Palm","details":"A stately, arching palm sold as a floor-plant statement, though its thirst and love of humidity make it a famous challenge indoors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ravenea%20rivularis%20as%20a%20houseplant.jpg?width=1024"},{"name":"King Air Plant","rarity":"legendary","id":"king-air-plant","subtitle":"Air Plant","details":"Tillandsia xerographica, the king of air plants: a slow rosette of broad, silvery, curling leaves that drinks through its scales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tillandsia%20xerographica%2020081016.jpg?width=1024"},{"name":"Jade Plant","rarity":"legendary","id":"jade-plant","subtitle":"Succulent","details":"A miniature tree of fleshy oval leaves; a symbol of luck and prosperity passed down through generations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crassula%20ovata%202012.jpg?width=1024"},{"name":"Echeveria 'Lola'","rarity":"legendary","id":"echeveria-lola","subtitle":"Succulent","details":"A sculpted rosette in pale mint and blush pink, dusted with farina; one of the most beloved hybrid echeverias.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20%27Lola%27%20%28Tangopaso%29%20D2506.jpg?width=1024"},{"name":"Burro's Tail","rarity":"legendary","id":"burros-tail","subtitle":"Succulent","details":"Long trailing stems plaited with plump blue-green beads; a hanging-basket classic that drops leaves at a touch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sedum%20morganianum%20%28donkey%27s%20tail%29.jpg?width=1024"},{"name":"Christmas Cactus","rarity":"legendary","id":"christmas-cactus","subtitle":"Cactus","details":"A jungle cactus with flat, segmented stems that erupts in pink and red trumpets in the depths of winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schlumbergera%20truncata%20kz01.jpg?width=1024"},{"name":"Rubber Plant","rarity":"legendary","id":"rubber-plant","subtitle":"Tree","details":"Ficus elastica's thick glossy leaves made it a mid-century icon; wounded stems weep the latex once tapped for rubber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ficus%20elastica%20Figowiec%20spr%C4%99%C5%BCysty%202023-10-31%2001.jpg?width=1024"},{"name":"Bird of Paradise","rarity":"legendary","id":"bird-of-paradise","subtitle":"Flowering","details":"Strelitzia nicolai grows banana-like leaves indoors; in bloom its flowers mimic a crane's head and beak.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Strelitzia%20larger.jpg?width=1024"},{"name":"African Violet","rarity":"legendary","id":"african-violet","subtitle":"Flowering","details":"Saintpaulia blooms nearly year-round under bright indoor light but sulks if cold water spots its fuzzy leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African%20violet%20%28Saintpaulia%29.jpg?width=1024"},{"name":"Peace Lily","rarity":"legendary","id":"peace-lily","subtitle":"Flowering","details":"Spathiphyllum's white sail-like spathes rise over glossy leaves; it droops dramatically when thirsty, then recovers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Spathiphyllum%20cannifolium%20%2814117377033%29.jpg?width=1024"},{"name":"Monstera 'Burle Marx Flame'","rarity":"epic","id":"monstera-burle-marx-flame","subtitle":"Cultivar","details":"A slow-growing Monstera whose mature leaves narrow into wavy, flame-like fingers; a jewel of serious collections.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20Burle%20marx%20flame-1-Vishuddhi%20garden-bengaluru-India.jpg?width=1024"},{"name":"Philodendron spiritus sancti","rarity":"epic","id":"philodendron-spiritus-sancti","subtitle":"Aroid","details":"The holy grail Philodendron: dagger leaves from a tiny Brazilian habitat, famed through collector lore and record sales.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20spiritus-sancti%20with%20hand.jpg?width=900"},{"name":"Philodendron billietiae","rarity":"epic","id":"philodendron-billietiae","subtitle":"Aroid","details":"Orange petioles and long, wavy-edged leaves; a climbing showpiece named for botanist Frieda Billiet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20billietiae%200zz.jpg?width=1024"},{"name":"Philodendron 'Florida Beauty'","rarity":"epic","id":"philodendron-florida-beauty","subtitle":"Cultivar","details":"A Florida-bred hybrid splashed with cream-to-yellow variegation across deeply lobed, antler-like leaves.","image":"https://foliage-factory.com/cdn/shop/files/philodendron-florida-beauty-foliage-01.webp?v=1782511470&width=1024"},{"name":"Philodendron verrucosum","rarity":"epic","id":"philodendron-verrucosum","subtitle":"Aroid","details":"Iridescent velvet leaves with glowing veins and fuzzy red-backed stems; loves the humidity of a terrarium.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/PhilodendronVerrucosum.jpg?width=1024"},{"name":"Monstera esqueleto","rarity":"epic","id":"monstera-esqueleto","subtitle":"Aroid","details":"The skeleton Monstera: mature leaves are mostly holes and lacy ribs, among the most fenestrated of all aroids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20friedrichsthalii2.jpg?width=1024"},{"name":"Rhaphidophora tetrasperma","rarity":"epic","id":"rhaphidophora-tetrasperma","subtitle":"Aroid","details":"Sold as Monstera minima, this fast Rhaphidophora climber wears split leaves like a miniature Monstera deliciosa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhaphidophora%20tetrasperma.jpg?width=1024"},{"name":"Anthurium warocqueanum","rarity":"epic","id":"anthurium-warocqueanum","subtitle":"Aroid","details":"The Queen Anthurium: long, narrow velvet leaves that can stretch over a metre in humid air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthurium%20waroqueanum.JPG?width=1024"},{"name":"Anthurium veitchii","rarity":"epic","id":"anthurium-veitchii","subtitle":"Aroid","details":"The King Anthurium, with deeply ribbed, rippled leaves that hang like green corrugated silk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthurium%20veitchii%2003.jpg?width=1024"},{"name":"Anthurium crystallinum","rarity":"epic","id":"anthurium-crystallinum","subtitle":"Aroid","details":"Velvet heart leaves with bold white veins; the species behind a generation of anthurium hybrids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alismatales%20-%20Anthurium%20crystallinum%202.jpg?width=1024"},{"name":"Epipremnum pinnatum 'Albo Variegata'","rarity":"epic","id":"epipremnum-pinnatum-albo-variegata","subtitle":"Cultivar","details":"A white-variegated climbing pothos relative whose leaves split and fenestrate as it climbs.","image":"https://tumbleweedplants.com/cdn/shop/products/Epipremnum-Pinnatum-_Albo-Variegata_-Tumbleweed-Plants-14615618.jpg?v=1761798409&width=200"},{"name":"Syngonium podophyllum 'Albo Variegatum'","rarity":"epic","id":"syngonium-podophyllum-albo-variegatum","subtitle":"Cultivar","details":"Arrowhead leaves splashed with unpredictable white sectors; no two leaves variegate alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Syngonium%20podophyllum%20albo-2-NRI%20Layout-bengaluru-India.jpg?width=1024"},{"name":"Stromanthe sanguinea 'Triostar'","rarity":"epic","id":"stromanthe-sanguinea-triostar","subtitle":"Cultivar","details":"Cream, pink, and green leaves with magenta undersides that fold upward at night in prayer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stromanthe%20sanguinea%20Triostar%201zz.jpg?width=1024"},{"name":"Hoya carnosa","rarity":"epic","id":"hoya-carnosa","subtitle":"Hoya","details":"The classic wax plant, passed down through generations; its waxy star blooms smell of chocolate at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_FR_2013.jpg?width=1024"},{"name":"Watermelon Peperomia","rarity":"epic","id":"watermelon-peperomia","subtitle":"Peperomia","details":"Silver-striped oval leaves mimic a watermelon rind so faithfully the plant is forever mistaken for a tiny melon patch.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Watermelon_Peperomia_%28Peperomia_argyreia%29.jpg?width=1024"},{"name":"Hoya pubicalyx","rarity":"epic","id":"hoya-pubicalyx","subtitle":"Hoya","details":"A fast, forgiving climber with long speckled leaves and burgundy star flowers; a first hoya for thousands of collectors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_pubicalyx_%28Silver_Pink%29.jpg?width=1024"},{"name":"Tradescantia zebrina","rarity":"epic","id":"tradescantia-zebrina","subtitle":"Trailer","details":"Silver-and-purple striped leaves root at every node; a cutting passed hand to hand has colonised windowsills worldwide.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20260317_Tradescantia_zebrina_01.jpg?width=1024"},{"name":"Hoya compacta","rarity":"epic","id":"hoya-compacta","subtitle":"Hoya","details":"The Hindu rope plant: leaves curl and twist into living green ropes that dangle from the pot like braided vines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_compacta_19.JPG?width=1024"},{"name":"Peperomia obtusifolia","rarity":"epic","id":"peperomia-obtusifolia","subtitle":"Peperomia","details":"The baby rubber plant: glossy spoon leaves on sturdy stems, famously tolerant of forgetful watering.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_obtusifolia%2C_Conservatorio_bot%C3%A1nico%2C_Fort_Wayne%2C_Indiana%2C_Estados_Unidos%2C_2012-11-12%2C_DD_01.jpg?width=1024"},{"name":"Boston Fern","rarity":"epic","id":"boston-fern","subtitle":"Fern","details":"Victorian parlours adored its arching fronds, especially the compact 'Bostoniensis' found as a sport in a Boston shipment.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nephrolepis%20exaltata%20indoor0705c.jpg?width=1024"},{"name":"Maidenhair Fern","rarity":"epic","id":"maidenhair-fern","subtitle":"Fern","details":"Fan-shaped leaflets dance on black, wiry stems; adored for its delicacy and notorious for sulking when its humidity drops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adiantum%20raddianum%202017%20sori.jpg?width=1024"},{"name":"Cattleya Orchid","rarity":"epic","id":"cattleya-orchid","subtitle":"Orchid","details":"The corsage orchid: huge, frilled, fragrant blooms that once defined elegance and still anchor orchid shows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cattleya%20Orchids.jpg?width=1024"},{"name":"Parlor Palm","rarity":"epic","id":"parlor-palm","subtitle":"Palm","details":"Victorian parlours' favourite palm tolerates low light and neglect, and stays a modest, elegant size for years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaedorea%20elegans%20Chamedora%20wytworna%202024-01-20%20Malaga%2005.jpg?width=900"},{"name":"Silver Vase Plant","rarity":"epic","id":"silver-vase-plant","subtitle":"Bromeliad","details":"Aechmea fasciata forms a silver-banded vase that holds rainwater in the wild; its pink bracted flower spike lasts for months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echmea%20wst%C4%99gowata%20%28Aechmea%20fasciata%29%20jasny%20kwiat%2001.jpg?width=1024"},{"name":"Tropical Pitcher Plant","rarity":"epic","id":"tropical-pitcher-plant","subtitle":"Carnivorous","details":"Nepenthes vines dangle pitchers of digestive fluid; the hardy hybrid x ventrata shrugs off windowsill life.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nepenthes%20x%20Ventrata%20pitcher.jpg?width=1024"},{"name":"Vanda Orchid","rarity":"epic","id":"vanda-orchid","subtitle":"Orchid","details":"Grown in bare baskets with roots hanging free, vandas spray their aerial roots daily and bloom in saturated blues and purples.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vanda%20coerulea%20orchid%20blooms%20from%20manipur.jpg?width=1024"},{"name":"Aloe Vera","rarity":"epic","id":"aloe-vera","subtitle":"Succulent","details":"Thick spears of soothing gel grown on sunny sills for millennia; the houseplant first-aid kit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloe%20vera%20%28Asphodelaceae%29.jpg?width=900"},{"name":"Zebra Plant","rarity":"epic","id":"zebra-plant","subtitle":"Succulent","details":"Dark green rosettes banded with raised white stripes, like a tiny zebra herd standing in a pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haworthiopsis%20attenuata%20%28Haw.%29%20G.%20D.%20Rowley%20-%20var.%20attenuata%20%27Carspitosa%27%20-%20par%20Mickael%20Schauli.jpg?width=1024"},{"name":"Golden Barrel","rarity":"epic","id":"golden-barrel","subtitle":"Cactus","details":"A perfect ribbed sphere armored in golden spines; the definitive potted barrel cactus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asiento%20de%20suegra%20%28Echinocactus%20grusonii%29%2C%20Jard%C3%ADn%20Bot%C3%A1nico%2C%20M%C3%BAnich%2C%20Alemania%2C%202013-09-08%2C%20DD%2002.JPG?width=1024"},{"name":"Living Stones","rarity":"epic","id":"living-stones","subtitle":"Succulent","details":"Lithops split stones that mimic pebbles, then astonish by pushing a daisy flower from the crack.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lithops%20lesliei%20ssp.%20lesliei%20v.%20mariae%20Cole%20141%2005.jpg?width=1024"},{"name":"Moon Cactus","rarity":"epic","id":"moon-cactus","subtitle":"Cactus","details":"A neon mutant cactus grafted onto a green rootstock stem; it cannot photosynthesize and lives entirely on its host.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gymnocalycium%20mihanovichii%208823.jpg?width=1024"},{"name":"Panda Plant","rarity":"epic","id":"panda-plant","subtitle":"Succulent","details":"Velvet leaves spotted chocolate at the tips, soft as a stuffed animal and just as strokeable.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Kalanchoe%20tomentosa%20-%20Leaves.jpg?width=1024"},{"name":"Weeping Fig","rarity":"epic","id":"weeping-fig","subtitle":"Tree","details":"Ficus benjamina is the classic indoor tree, though it famously drops leaves in protest after being moved.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ficus%20benjamina%2010zz.jpg?width=900"},{"name":"Cyclamen","rarity":"epic","id":"cyclamen","subtitle":"Flowering","details":"Cyclamen persicum's swept-back petals bloom through winter, then the whole plant naps through summer dormancy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CyclamenPersicumMill20.jpg?width=1024"},{"name":"Amaryllis","rarity":"epic","id":"amaryllis","subtitle":"Flowering","details":"Hippeastrum bulbs force giant trumpet blooms indoors in winter from a bulb often sold bare, in a box, with no soil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amaryllis%20%28Hippeastrum%29%2018-01-2025.%20%28actm.%29%2004.jpg?width=1024"},{"name":"Money Tree","rarity":"epic","id":"money-tree","subtitle":"Tree","details":"Pachira aquatica is sold with braided trunks and hand-shaped leaves, long kept as a symbol of good fortune.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pachira%20aquatica%2C%20money%20tree%2C%20munguba%20park%20ceret%20sao%20paulo%20brazil.jpg?width=1024"},{"name":"Umbrella Tree","rarity":"epic","id":"umbrella-tree","subtitle":"Tree","details":"Schefflera actinophylla fans its leaflets in perfect parasol whorls and grows fast into a full indoor canopy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Umbrella%20tree%20%28Schefflera%20actinophylla%29%203.jpg?width=1024"},{"name":"Medinilla","rarity":"epic","id":"medinilla","subtitle":"Flowering","details":"Medinilla magnifica drapes chandelier-like clusters of pink bracts and berries, earning its 'Magnificent' name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20260317%20Medinilla%20magnifica%2001.jpg?width=1024"},{"name":"Philodendron 'White Knight'","rarity":"rare","id":"philodendron-white-knight","subtitle":"Cultivar","details":"Deep green leaves marbled with white, held on dark burgundy-purple stems; the moody member of the royal trio.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20White%20Knight-2-NRI%20Layout-bengaluru-India.jpg?width=1024"},{"name":"Philodendron 'Ring of Fire'","rarity":"rare","id":"philodendron-ring-of-fire","subtitle":"Cultivar","details":"Serrated leaves edged like a saw blade, variegated in cream, gold and sunset orange as they mature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20Ring%20Of%20Fire-1-NRI%20Layout-bengaluru-India.jpg?width=1024"},{"name":"Philodendron 'Florida Ghost'","rarity":"rare","id":"philodendron-florida-ghost","subtitle":"Cultivar","details":"New leaves unfurl ghost-white, then fade through mint to deep green, so one plant wears every shade at once.","image":"https://www.plantstudio.ae/cdn/shop/files/IMG_8365.jpg?crop=center&height=1200&v=1737103546&width=1200"},{"name":"Philodendron pastazanum","rarity":"rare","id":"philodendron-pastazanum","subtitle":"Aroid","details":"A ground-creeping giant with glossy, quilted heart leaves and bold white veins, kin to gloriosum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20pastazanum.jpg?width=900"},{"name":"Philodendron plowmanii","rarity":"rare","id":"philodendron-plowmanii","subtitle":"Aroid","details":"Ruffled, winged petioles carry camouflage-patterned heart leaves across the soil surface as it creeps.","image":"https://inaturalist-open-data.s3.amazonaws.com/photos/109361447/large.jpeg"},{"name":"Monstera dubia","rarity":"rare","id":"monstera-dubia","subtitle":"Aroid","details":"A shingle plant: juvenile leaves press flat to bark in a silver-patterned mosaic before transforming with age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20dubia%20%28Kunth%29%20Engl.%20%26%20K.Krause%20-%20par%20Mickael%20Schauli.jpg?width=1024"},{"name":"Monstera siltepecana","rarity":"rare","id":"monstera-siltepecana","subtitle":"Aroid","details":"Silver-veined juvenile leaves climb and split into green fenestrated blades; sold in trade as El Salvador form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20siltepecana%20kz01.jpg?width=1024"},{"name":"Philodendron atabapoense","rarity":"rare","id":"philodendron-atabapoense","subtitle":"Aroid","details":"Slim arrowhead leaves with burgundy undersides, dangling like green knives from a climbing stem.","image":"https://inaturalist-open-data.s3.amazonaws.com/photos/250281605/medium.jpeg"},{"name":"Philodendron 'Burle Marx Variegata'","rarity":"rare","id":"philodendron-burle-marx-variegata","subtitle":"Cultivar","details":"A variegated form of burle-marxii splashed in cream and chartreuse; unstable colour makes every leaf a lottery.","image":"https://foliage-factory.com/cdn/shop/files/philodendron-burle-marx-variegata-06.webp?v=1776361792&width=960"},{"name":"Philodendron joepii","rarity":"rare","id":"philodendron-joepii","subtitle":"Aroid","details":"A near-mythical species with guitar-shaped leaves, long known from a single wild collection in French Guiana.","image":"https://www.logees.com/cdn/shop/files/philodendron_joepii_sm.jpg?v=1751919894"},{"name":"Alocasia baginda 'Dragon Scale'","rarity":"rare","id":"alocasia-baginda-dragon-scale","subtitle":"Cultivar","details":"Leaves textured like a dragon's hide, deep veins pressed into a metallic green surface.","image":"https://www.bumbleplants.com/cdn/shop/products/AlocasiaBaginda_DragonScale_13.jpg?v=1740371129&width=1800"},{"name":"Alocasia cuprea 'Red Secret'","rarity":"rare","id":"alocasia-cuprea-red-secret","subtitle":"Cultivar","details":"Metallic copper-red leaves that shine like polished metal under bright light.","image":"https://foliage-factory.com/cdn/shop/files/alocasia-cuprea-red-secret-medium-07.webp?v=1779664377&width=1200"},{"name":"Anthurium regale","rarity":"rare","id":"anthurium-regale","subtitle":"Aroid","details":"A stately Peruvian species with huge velvet leaves and contrasting pale veins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20150224%20083943%20-%20Edited.jpg?width=1024"},{"name":"Anthurium magnificum","rarity":"rare","id":"anthurium-magnificum","subtitle":"Aroid","details":"Large quilted heart leaves with bright white veins, from Colombian cloud forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthurium%20magnificum%20Linden%20-%20par%20Mickael%20Schauli.jpg?width=1024"},{"name":"Colocasia esculenta 'Mojito'","rarity":"rare","id":"colocasia-esculenta-mojito","subtitle":"Cultivar","details":"Elephant-ear leaves speckled and streaked with dark purple-black over fresh green.","image":"https://cdn.shopify.com/s/files/1/0549/4534/9796/products/Colocasia-Mojito5_db7b6029-9e43-4d50-9a5e-b2176a0b5da3_2048x.jpg?v=1618321697"},{"name":"Epipremnum aureum 'Manjula'","rarity":"rare","id":"epipremnum-aureum-manjula","subtitle":"Cultivar","details":"Broad, wavy leaves painted with swirls of white, cream, and green on each leaf.","image":"https://brownspointplants.com/cdn/shop/files/6_POTHOS_MANJULA_2.jpg?v=1764452146&width=600"},{"name":"Scindapsus treubii 'Moonlight'","rarity":"rare","id":"scindapsus-treubii-moonlight","subtitle":"Cultivar","details":"Sterling-silver leaves on a slow, shingling vine; patience earns a curtain of metal.","image":"https://growtropicals.com/cdn/shop/products/scindapsus-treubii-moonlight-plants-growtropicals-532895.jpg?v=1652549315&width=800"},{"name":"Dieffenbachia 'Reflector'","rarity":"rare","id":"dieffenbachia-reflector","subtitle":"Cultivar","details":"Deep green leaves flecked with lime and cream that seem to glow in low light.","image":"https://www.myhomenature.com/cdn/shop/products/dumb_cane_dieffenbachia_reflector_c27ffe3b-08de-4fab-9434-d15908901887.jpg?v=1692879297&width=1646"},{"name":"Calathea warscewiczii","rarity":"rare","id":"calathea-warscewiczii","subtitle":"Prayer Plant","details":"The Jungle Velvet calathea: fuzzy deep-green leaves with a pale feather down the centre.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calathea%20warscewiczii%205zz.jpg?width=1024"},{"name":"Maranta leuconeura 'Lemon Lime'","rarity":"rare","id":"maranta-leuconeura-lemon-lime","subtitle":"Cultivar","details":"Chartreuse veins blaze down each leaf; at night the leaves fold upward in prayer.","image":"https://thespellcraftstore.com/cdn/shop/files/lemon-lime.jpg?v=1771720533&width=1445"},{"name":"Aglaonema 'Silver Bay'","rarity":"rare","id":"aglaonema-silver-bay","subtitle":"Cultivar","details":"Broad leaves centred with silver; one of the toughest and most forgiving Chinese evergreens.","image":"https://hortology.co.uk/cdn/shop/products/Aglaonema-Silver-Bay-Chinese-Evergreen-Leaves_2000x.jpg?v=1714037303"},{"name":"Hoya carnosa 'Krimson Princess'","rarity":"rare","id":"hoya-carnosa-krimson-princess","subtitle":"Cultivar","details":"The inside-out Krimson Queen: green-edged leaves with cream and pink centres that blush brighter in strong light.","image":"https://www.bybrittanygoldwyn.com/wp-content/uploads/2021/09/Hoya-Carnosa-Krimson-Princess-1-720x960.jpg"},{"name":"String of Turtles","rarity":"rare","id":"string-of-turtles","subtitle":"Peperomia","details":"Tiny round leaves veined like turtle shells creep over the pot's edge; a terrarium and shelf-edge favourite.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Peperomia_prostrata_a1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Raindrop Peperomia","rarity":"rare","id":"raindrop-peperomia","subtitle":"Peperomia","details":"Glossy teardrop leaves held upright like raindrops frozen mid-fall; often confused with the coin plant Pilea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coin_Leaf_Peperomia_%28Peperomia_polybotrya_%27Jayde%27%29_1.jpg?width=1024"},{"name":"Hoya obovata","rarity":"rare","id":"hoya-obovata","subtitle":"Hoya","details":"Big round splash-marked leaves and a vigorous climbing habit make this one of the boldest foliage hoyas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_obovata.jpg?width=1024"},{"name":"English Ivy","rarity":"rare","id":"english-ivy","subtitle":"Vine","details":"The timeless trailing ivy of hanging baskets and topiary frames; aerial rootlets let it climb almost anything.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hedera_helix_Dover.jpg?width=1024"},{"name":"Purple Heart","rarity":"rare","id":"purple-heart","subtitle":"Trailer","details":"Violet-purple leaves and stems deepen in colour with sun; a single cutting spreads into a royal carpet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tradescantia_pallida_Flower_1.jpg?width=1024"},{"name":"Creeping Fig","rarity":"rare","id":"creeping-fig","subtitle":"Vine","details":"Minute heart leaves hug walls and terrarium glass in a dense green mat, glued on by tiny aerial roots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ficus_pumila_%28Leafs%29.jpg?width=1024"},{"name":"Hoya australis","rarity":"rare","id":"hoya-australis","subtitle":"Hoya","details":"A robust Australian climber with succulent round leaves and honey-scented white blooms loved by night moths.","image":"https://upload.wikimedia.org/wikipedia/commons/6/60/Hoya_australis_tonga.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Ripple Peperomia","rarity":"rare","id":"ripple-peperomia","subtitle":"Peperomia","details":"Deeply quilted, corrugated leaves give this compact peperomia its crumpled-silk look in green, red, or silver.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_Caperata_Cultivar_Plant_Green_Aug25_A7CR_06609.jpg?width=1024"},{"name":"String of Dolphins","rarity":"rare","id":"string-of-dolphins","subtitle":"Trailer","details":"Each curved leaf sports two tiny fins, so the whole strand reads as a pod of dolphins leaping from the pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dolphinplant.jpg?width=1024"},{"name":"Asparagus Fern","rarity":"rare","id":"asparagus-fern","subtitle":"Fern","details":"Not a true fern at all: a scrambling asparagus relative whose needle-fine 'leaves' are really flattened stems called cladodes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr%20050517-9003%20Asparagus%20setaceus.jpg?width=900"},{"name":"Rabbit's Foot Fern","rarity":"rare","id":"rabbits-foot-fern","subtitle":"Fern","details":"Furry rhizomes creep over the pot rim like rabbits' feet, sprouting lacy fronds; the 'feet' root new plants where they touch soil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Davallia%20fejeensis%20kz03.jpg?width=1024"},{"name":"Kangaroo Paw Fern","rarity":"rare","id":"kangaroo-paw-fern","subtitle":"Fern","details":"Thick, furry rhizomes hop over the pot edge while two frond shapes share one plant: plain straps and forked, lobed blades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Microsorum%20diversifolium%20-%20US%20Botanic%20Gardens%20-%20Sarah%20Stierch.jpg?width=1024"},{"name":"Dendrobium Orchid","rarity":"rare","id":"dendrobium-orchid","subtitle":"Orchid","details":"Cane-like pseudobulbs carry sprays of flowers; many dendrobiums rest in winter, then bloom from bare old canes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RFE06%20white%20orchid%20Dendrobium%20cultivars.jpg?width=1024"},{"name":"Lady Slipper Orchid","rarity":"rare","id":"lady-slipper-orchid","subtitle":"Orchid","details":"Paphiopedilum's waxy pouch traps insects so they must brush past the pollen to escape, ensuring pollination.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paphiopedilum%20flower%2002.jpg?width=1024"},{"name":"Guzmania","rarity":"rare","id":"guzmania","subtitle":"Bromeliad","details":"A tank bromeliad whose scarlet or orange bract star crowns a rosette of strap leaves for months at a time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Guzmania%20lingulata%205730.jpg?width=1024"},{"name":"Tillandsia ionantha","rarity":"rare","id":"tillandsia-ionantha","subtitle":"Air Plant","details":"A tiny air plant that blushes scarlet at bloom time, then offsets into clumps that can become a living ball of pups.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tillandsia%20ionantha%20%28luchtplantje%29.%2020-12-2020.%20%28actm.%29%2001.jpg?width=1024"},{"name":"Cape Sundew","rarity":"rare","id":"cape-sundew","subtitle":"Carnivorous","details":"Drosera capensis tentacles glitter with sticky mucilage and slowly curl around trapped flies; it is nearly weed-tough in a sunny bog pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Drosera%20capensis%20Luc%20Viatour.jpg?width=1024"},{"name":"Sago Palm","rarity":"rare","id":"sago-palm","subtitle":"Palm","details":"Not a palm but an ancient cycad, it flushes a crown of stiff fronds all at once from a rough, slow-growing trunk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cycas%20revoluta1327A.JPG?width=1024"},{"name":"Kentia Palm","rarity":"rare","id":"kentia-palm","subtitle":"Palm","details":"Graceful and slow, the kentia was the Victorian status palm; its slowness and island origin still make it a premium floor plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Howea%20forsteriana%208zz.jpg?width=1024"},{"name":"Elkhorn Fern","rarity":"rare","id":"elkhorn-fern","subtitle":"Fern","details":"An Australian platycerium with simpler, more upright antler fronds than its staghorn cousin, grown mounted or in baskets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Platycerium%20hillii%20SF26217-06.jpg?width=900"},{"name":"Echeveria elegans","rarity":"rare","id":"echeveria-elegans","subtitle":"Succulent","details":"The Mexican snowball: tight, pale blue-white rosettes that pup freely into whole colonies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria-elegans-rose.jpg?width=1024"},{"name":"Ghost Plant","rarity":"rare","id":"ghost-plant","subtitle":"Succulent","details":"Opalescent rosettes that blush pink in sun and trail from baskets; a single leaf can start a new plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Graptopetalum%20paraguayense%20-%20leaves.jpg?width=1024"},{"name":"Hens and Chicks","rarity":"rare","id":"hens-and-chicks","subtitle":"Succulent","details":"A mother rosette ringed by chick offsets in a terracotta pot; nearly impossible to kill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sempervivum%20tectorum%20%28diameter%2015%20cm%29.jpg?width=1024"},{"name":"Mother of Thousands","rarity":"rare","id":"mother-of-thousands","subtitle":"Succulent","details":"Tiny plantlets line every leaf edge, drop, and root where they land; one plant becomes a crowd.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vivipary%20in%20Kalanchoe%20daigremontiana.jpg?width=1024"},{"name":"Bunny Ear Cactus","rarity":"rare","id":"bunny-ear-cactus","subtitle":"Cactus","details":"Flat green pads sprout in pairs like rabbit ears, dotted with fuzzy golden glochids that bite back.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Opuntia%20microdasys%20var%20angelwings.jpg?width=1024"},{"name":"Thanksgiving Cactus","rarity":"rare","id":"thanksgiving-cactus","subtitle":"Cactus","details":"Pointed, claw-edged stem segments and satiny blooms that arrive a month before its Christmas cousin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mi%20cactus%20de%20Navidad%20%2815827279151%29.jpg?width=1024"},{"name":"Mistletoe Cactus","rarity":"rare","id":"mistletoe-cactus","subtitle":"Cactus","details":"A spineless jungle cactus of pencil-thin trailing stems, finished with translucent white berries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhipsalis%20baccifera%20kz01.jpg?width=1024"},{"name":"Elephant Bush","rarity":"rare","id":"elephant-bush","subtitle":"Succulent","details":"Red stems carry tiny round jade-like leaves; a favorite bonsai subject and, in Africa, elephant fodder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portulacaria%20afra%2002.JPG?width=1024"},{"name":"Crown of Thorns","rarity":"rare","id":"crown-of-thorns","subtitle":"Succulent","details":"Thorn-armed stems that flower almost year-round in red and pink bracts on the sunniest sill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Euphorbia%20milii%202915.jpg?width=1024"},{"name":"Bear's Paw","rarity":"rare","id":"bears-paw","subtitle":"Succulent","details":"Chubby, fuzzy leaves tipped with dark claws, arranged exactly like a tiny bear's paw.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cotyledon%20tomentosa%20in%20cultivation%20-%20Cape%20Town%209.jpg?width=1024"},{"name":"Clivia","rarity":"rare","id":"clivia","subtitle":"Flowering","details":"Clivia miniata needs a cool, dry winter rest indoors before rewarding patience with dense orange trumpet clusters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Clivia%20miniata%20%28Bush%20lily%29%20flowers.jpg?width=1024"},{"name":"Hibiscus","rarity":"rare","id":"hibiscus","subtitle":"Flowering","details":"Hibiscus rosa-sinensis opens hand-sized tropical blooms on a sunny windowsill, each flower lasting about a day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hibiscus%20rosa-sinensis%20flower%202.JPG?width=1024"},{"name":"Jasmine","rarity":"rare","id":"jasmine","subtitle":"Flowering","details":"Jasminum polyanthum twines over indoor trellises and perfumes whole rooms with starry white winter blooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Jasminum%20polyanthum%20%E2%80%93%20flowers%20and%20buds.jpg?width=1024"},{"name":"Rex Begonia","rarity":"rare","id":"rex-begonia","subtitle":"Foliage","details":"Begonia rex is grown not for flowers but for spiralled leaves painted in silver, burgundy and near-black.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Begonia%20rex-cultorum%202%2C%20Korkenzieher%20Begonie%2C%20Botanical%20Garden%20Heidelberg.JPG?width=1024"},{"name":"Dragon Tree","rarity":"rare","id":"dragon-tree","subtitle":"Tree","details":"Dracaena marginata's slender canes and red-edged sword leaves make it a sculptural, drought-tolerant corner tree.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dracaena%20marginata%20IndoorPlant%200605k.jpg?width=1024"},{"name":"Ponytail Palm","rarity":"rare","id":"ponytail-palm","subtitle":"Tree","details":"Beaucarnea recurvata stores water in its swollen trunk base and erupts in a fountain of ribbon-like leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Beaucarnea%20recurvata%20kz03.jpg?width=900"},{"name":"Olive Tree","rarity":"rare","id":"olive-tree","subtitle":"Tree","details":"Olea europaea grown in a pot brings silvery Mediterranean foliage indoors, craving the brightest sun available.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olive%20tree%20in%20jar%202016d.jpg?width=1024"},{"name":"Meyer Lemon","rarity":"rare","id":"meyer-lemon","subtitle":"Tree","details":"Citrus x meyeri fruits happily in a sunny indoor pot, bearing fragrant blossom and sweet lemons at the same time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MeyerLemon.jpg?width=1024"},{"name":"Terrarium","rarity":"rare","id":"terrarium","subtitle":"Terrarium","details":"A glass garden under cover recycles its own humidity, letting tiny tropical plants thrive in dry heated rooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Terrarium%20by%20plantlover93.jpg?width=900"},{"name":"Wardian Case","rarity":"rare","id":"wardian-case","subtitle":"Terrarium","details":"This sealed glass case let living plants survive months-long sea voyages and reshaped the world's gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wardian%20case%20-%20Christchurch%20Botanic%20Gardens%20-%20Christchurch%2C%20NZ%20-%20DSC00526.jpg?width=1024"},{"name":"Monstera subpinnata","rarity":"uncommon","id":"monstera-subpinnata","subtitle":"Aroid","details":"A climber whose mature leaves divide into feathery, almost palm-like leaflets along a central rib.","image":"https://static.inaturalist.org/photos/642112672/large.jpg"},{"name":"Monstera lechleriana","rarity":"uncommon","id":"monstera-lechleriana","subtitle":"Aroid","details":"Sturdy oval leaves pierced by a row of holes along the midrib; a tough, fast climber for a moss pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20lechleriana.jpg?width=1024"},{"name":"Monstera standleyana","rarity":"uncommon","id":"monstera-standleyana","subtitle":"Aroid","details":"Glossy lance leaves with no holes at all, sometimes flecked with cream; the Monstera that breaks the rules.","image":"https://inaturalist-open-data.s3.amazonaws.com/photos/553505257/large.jpg"},{"name":"Monstera karsteniana","rarity":"uncommon","id":"monstera-karsteniana","subtitle":"Aroid","details":"Sold as Monstera 'Peru': bullate, deep-green leaves with a hammered, almost reptilian texture.","image":"https://todaysgardener.com/wp-content/uploads/2021/05/rsz_karst-768x683.jpg"},{"name":"Monstera pinnatipartita","rarity":"uncommon","id":"monstera-pinnatipartita","subtitle":"Aroid","details":"Leaves split deep toward the midrib as they mature, over a speckled, bumpy petiole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera_pinnatipartita_in_Colombia.jpg?width=900"},{"name":"Monstera adansonii 'Variegata'","rarity":"uncommon","id":"monstera-adansonii-variegata","subtitle":"Cultivar","details":"The Swiss cheese vine splashed with white and mint variegation; each holed leaf patterns differently.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20deliciosa%20variegata.jpg?width=1024"},{"name":"Monstera epipremnoides","rarity":"uncommon","id":"monstera-epipremnoides","subtitle":"Aroid","details":"A cloud-forest species with thick, heavily windowed leaves, long confused with the esqueleto form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20epipremnoides.jpg?width=1024"},{"name":"Philodendron 'Birkin'","rarity":"uncommon","id":"philodendron-birkin","subtitle":"Cultivar","details":"Compact rosettes of deep green leaves pinstriped in creamy white; a spontaneous mutation of 'Rojo Congo'.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20birkin-3-RM%20Nagar-bangalore-India.jpg?width=900"},{"name":"Philodendron 'White Wizard'","rarity":"uncommon","id":"philodendron-white-wizard","subtitle":"Cultivar","details":"Broad green leaves splashed with clean white variegation on green stems edged in white.","image":"https://live.staticflickr.com/65535/52577938159_0aba11135a_b.jpg"},{"name":"Philodendron 'Brasil'","rarity":"uncommon","id":"philodendron-brasil","subtitle":"Cultivar","details":"A heart-leaf vine splashed with chartreuse down the centre of every leaf, named for Brazil's flag colours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20hederaceum%20hederaceum%20Brasil%200zz.jpg?width=1024"},{"name":"Philodendron micans","rarity":"uncommon","id":"philodendron-micans","subtitle":"Aroid","details":"Velvet heart leaves in bronze and deep green with a satin sheen; trails beautifully from a high shelf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20hederaceum%20kz1.jpg?width=1024"},{"name":"Philodendron squamiferum","rarity":"uncommon","id":"philodendron-squamiferum","subtitle":"Aroid","details":"Hairy red bristles coat its stems like a bottle brush, under oak-shaped leaves; a true oddball climber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20squamiferum%20-%20Berlin%20Botanical%20Garden%20-%20IMG%208719.JPG?width=900"},{"name":"Philodendron pedatum","rarity":"uncommon","id":"philodendron-pedatum","subtitle":"Aroid","details":"The oak-leaf Philodendron: glossy blades cut into deep lobes, on long stems with reddish bases.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20pedatum%20kz01.jpg?width=900"},{"name":"Philodendron mayoi","rarity":"uncommon","id":"philodendron-mayoi","subtitle":"Aroid","details":"Palm-like leaves fan into slender fingers; a Brazilian species that brings a tropical canopy look indoors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20mayoi%20%2814455374705%29.jpg?width=1024"},{"name":"Philodendron camposportoanum","rarity":"uncommon","id":"philodendron-camposportoanum","subtitle":"Aroid","details":"Small velvety leaves shift from pink-bronze bells to three-lobed green blades as the plant climbs.","image":"https://inaturalist-open-data.s3.amazonaws.com/photos/242522240/large.jpeg"},{"name":"Philodendron brandtianum","rarity":"uncommon","id":"philodendron-brandtianum","subtitle":"Aroid","details":"The silver leaf Philodendron: olive hearts dusted with metallic silver that fades as leaves mature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron_brandtianum_in_Colombia.jpg?width=900"},{"name":"Philodendron sodiroi","rarity":"uncommon","id":"philodendron-sodiroi","subtitle":"Aroid","details":"Blue-green heart leaves mottled with silver clouds, on wiry red stems; a dainty Andean climber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20ornatum%20kz1.jpg?width=1024"},{"name":"Epipremnum aureum 'Marble Queen'","rarity":"uncommon","id":"epipremnum-aureum-marble-queen","subtitle":"Cultivar","details":"Heavily marbled white-and-green leaves; grows slower than plain pothos but far brighter.","image":"https://growtropicals.com/cdn/shop/articles/epipremnum-marble-queen-plants-growtropicals-12cm-638397_0abe9ed4-a626-4317-92db-74a5265f2eca.jpg?v=1785593903&width=760"},{"name":"Epipremnum aureum 'Neon'","rarity":"uncommon","id":"epipremnum-aureum-neon","subtitle":"Cultivar","details":"Electric chartreuse leaves that hold their glow even in a dim corner of the room.","image":"https://153048755.cdn6.editmysite.com/uploads/1/5/3/0/153048755/IMI4FEIP7KLXY3H4EEXSQO3B.jpeg?width=2400&optimize=medium"},{"name":"Epipremnum aureum 'Pearls and Jade'","rarity":"uncommon","id":"epipremnum-aureum-pearls-and-jade","subtitle":"Cultivar","details":"Small leaves flecked with white, cream, and grey-green; a speckled sport of Marble Queen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Money%20Plant%20%28Epipremnum%20aureum%20%27N%27%20Joy%27%29%202%20%28cropped%29.jpg?width=1024"},{"name":"Epipremnum pinnatum 'Cebu Blue'","rarity":"uncommon","id":"epipremnum-pinnatum-cebu-blue","subtitle":"Cultivar","details":"Silvery blue-green leaves that split into deep fenestrations when allowed to climb.","image":"https://growtropicals.com/cdn/shop/products/epipremnum-pinnatum-cebu-blue-plants-growtropicals-12cm-131516.jpg?v=1674843269&width=800"},{"name":"Scindapsus pictus 'Argyraeus'","rarity":"uncommon","id":"scindapsus-pictus-argyraeus","subtitle":"Cultivar","details":"The Satin Pothos: velvety heart leaves dusted with silver spots that catch the light.","image":"https://i.etsystatic.com/25639060/r/il/e2f290/6245865716/il_794xN.6245865716_qbgk.jpg"},{"name":"Alocasia micholitziana 'Frydek'","rarity":"uncommon","id":"alocasia-micholitziana-frydek","subtitle":"Aroid","details":"Velvet arrow leaves with stark white veins; the green Frydek is a shelf classic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alocasia%20micholitziana%20%27Frydek%27.jpg?width=1024"},{"name":"Alocasia zebrina","rarity":"uncommon","id":"alocasia-zebrina","subtitle":"Aroid","details":"Arrow leaves held high on zebra-striped stems banded in black and cream.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alocasia%20zebrina%204zz.jpg?width=1024"},{"name":"Alocasia macrorrhizos 'Variegata'","rarity":"uncommon","id":"alocasia-macrorrhizos-variegata","subtitle":"Cultivar","details":"Giant elephant-ear leaves splashed with bold white variegation, different on every leaf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alocasia%20macrorrhizos%20Variegata%201zz.jpg?width=1024"},{"name":"Anthurium andraeanum","rarity":"uncommon","id":"anthurium-andraeanum","subtitle":"Aroid","details":"The Flamingo Flower: waxy heart-shaped spathes in red, pink, or white that last for weeks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthurium%20%28Flamingoplant%29%2012-08-2019%20%28actm%29%2001.jpg?width=1024"},{"name":"Alocasia amazonica 'Bambino'","rarity":"uncommon","id":"alocasia-amazonica-bambino","subtitle":"Cultivar","details":"A miniature Polly with narrow, sharply lobed dark leaves and bright pale veins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alocasia%20x%20amazonica%20a2.jpg?width=1024"},{"name":"Anthurium forgetii","rarity":"uncommon","id":"anthurium-forgetii","subtitle":"Aroid","details":"Round, shield-like velvet leaves with silver veins and no sinus where leaf meets stem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthurium%20forgetii%20potted.jpg?width=1024"},{"name":"Syngonium podophyllum 'Pink Splash'","rarity":"uncommon","id":"syngonium-podophyllum-pink-splash","subtitle":"Cultivar","details":"Arrowhead leaves washed and speckled with bubblegum pink over fresh green.","image":"https://cdn.monstera-app.com/p/a364ce7f929570a6d2ab36f208b249552179f60091c432bfcfe4d1002d9132d0.jpg/syngonium-pink-leaves-pink-splash.webp"},{"name":"Syngonium podophyllum 'Milk Confetti'","rarity":"uncommon","id":"syngonium-podophyllum-milk-confetti","subtitle":"Cultivar","details":"Milky white-green leaves confettied with pink spots; every leaf is a small celebration.","image":"https://thespellcraftstore.com/cdn/shop/files/syngonium-syngonium-milk-confetti-4-2.webp?v=1773871167&width=1426"},{"name":"Dieffenbachia 'Camille'","rarity":"uncommon","id":"dieffenbachia-camille","subtitle":"Cultivar","details":"Creamy white leaf centres edged in deep green; a bright, compact dumb cane.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr%20080117-1528%20Dieffenbachia%20maculata.jpg?width=1024"},{"name":"Caladium 'White Christmas'","rarity":"uncommon","id":"caladium-white-christmas","subtitle":"Cultivar","details":"Paper-thin white leaves veined in green, glowing like stained glass in shade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caladium%20bicolor%20%27White%20Christmas%27%20%28181217-1614%29.jpg?width=1024"},{"name":"Calathea roseopicta 'Medallion'","rarity":"uncommon","id":"calathea-roseopicta-medallion","subtitle":"Cultivar","details":"Feather-patterned leaves in deep and pale greens with purple undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr%20070906-8758%20Calathea%20roseopicta.jpg?width=1024"},{"name":"Calathea makoyana","rarity":"uncommon","id":"calathea-makoyana","subtitle":"Prayer Plant","details":"The Peacock Plant: translucent leaves painted with dark green ovals like a tail feather.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calathea%20makoyana.jpg?width=1024"},{"name":"Ctenanthe burle-marxii","rarity":"uncommon","id":"ctenanthe-burle-marxii","subtitle":"Prayer Plant","details":"The Fishbone Plant: pale leaves striped with dark herringbone bands, purple beneath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ctenanthe%20burle-marxii%201.jpg?width=1024"},{"name":"Hoya wayetii","rarity":"uncommon","id":"hoya-wayetii","subtitle":"Hoya","details":"Slim dark-edged leaves flush burgundy in bright light, spilling neatly over the rim of hanging pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_wayetii_%283610163309%29.jpg?width=1024"},{"name":"Hoya retusa","rarity":"uncommon","id":"hoya-retusa","subtitle":"Hoya","details":"Grass-thin flat leaves on a fountain of stems; its single white flowers look like tiny shooting stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_retusa.jpg?width=1024"},{"name":"Peperomia 'Hope'","rarity":"uncommon","id":"peperomia-hope","subtitle":"Cultivar","details":"A trailing hybrid with coin-round leaves in whorls of three and four, bred for baskets and terrariums.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_tetraphylla_Hope-1-Vishuddhi_garden-bengaluru-India.jpg?width=1024"},{"name":"Peperomia obtusifolia 'Variegata'","rarity":"uncommon","id":"peperomia-obtusifolia-variegata","subtitle":"Cultivar","details":"The marbled baby rubber plant: cream-splashed glossy leaves that ask only for bright light to stay bold.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Variegated_Peperomia_%28Peperomia_obtusifolia_%27Variegata%27%29.jpg?width=1024"},{"name":"Hoya bilobata","rarity":"uncommon","id":"hoya-bilobata","subtitle":"Hoya","details":"A petite Philippine hoya with tiny oval leaves on wiry trailing stems and small clusters of fuzzy pink blooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya%20bilobata.jpg?width=1024"},{"name":"Hoya lacunosa","rarity":"uncommon","id":"hoya-lacunosa","subtitle":"Hoya","details":"Tiny veiny leaves and fuzzy cream blossoms with a cinnamon-like perfume, flowering again and again all year.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_lacunosa.JPG?width=1024"},{"name":"Tradescantia 'Tricolor'","rarity":"uncommon","id":"tradescantia-tricolor","subtitle":"Cultivar","details":"Leaves striped pink, cream, and green blush deeper in bright light; a candy-striped trailer for sunny shelves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tradescantia%20Fluminensis%20Tri-Color.jpg?width=1024"},{"name":"String of Nickels","rarity":"uncommon","id":"string-of-nickels","subtitle":"Trailer","details":"Flat round silver-green discs strung along fine stems, an epiphyte that hugs bark and hanging mounts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dischidia_nummularia_%28Habius%29.jpg?width=1024"},{"name":"Hoya bella","rarity":"uncommon","id":"hoya-bella","subtitle":"Hoya","details":"A dainty basket hoya whose white-and-rose star flowers hang like miniature chandeliers above slender leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_lanceolata_subsp._bella_%2814522128231%29.jpg?width=1024"},{"name":"Swedish Ivy","rarity":"uncommon","id":"swedish-ivy","subtitle":"Trailer","details":"Scalloped glossy leaves on fast trailing stems; a Victorian parlour staple despite being neither Swedish nor ivy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plectranthus%20verticillatus%2001.jpg?width=1024"},{"name":"Happy Bean","rarity":"uncommon","id":"happy-bean","subtitle":"Peperomia","details":"Pea-pod leaves split along a dark window stripe, storing water for dry spells in its native Peru.","image":"https://completegardening.com/wp-content/uploads/2025/04/Peperomia-ferreyrae-Happy-Bean.jpg"},{"name":"Moses-in-the-Cradle","rarity":"uncommon","id":"moses-in-the-cradle","subtitle":"Trailer","details":"Purple-backed boat-shaped leaves cradle tiny white flowers, the 'Moses' hidden in the bracts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moses_in_the_cradle_%28Tradescantia_spathacea%29_5.jpg?width=1024"},{"name":"Grape Ivy","rarity":"uncommon","id":"grape-ivy","subtitle":"Vine","details":"Glossy three-part leaves like a grapevine's make this a classic, shade-tolerant climber for trellises indoors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cissus_alata_Cissus_rombolistny_2023-10-31_01.jpg?width=1024"},{"name":"Hoya linearis","rarity":"uncommon","id":"hoya-linearis","subtitle":"Hoya","details":"Pencil-thin fuzzy leaves pour from hanging pots in soft green curtains from its Himalayan homeland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_linearis.jpg?width=1024"},{"name":"Ruby Glow Peperomia","rarity":"uncommon","id":"ruby-glow-peperomia","subtitle":"Peperomia","details":"Succulent leaves glow green above and ruby red beneath, held on red stems like tiny desert lanterns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_graveolens1.jpg?width=1024"},{"name":"String of Bananas","rarity":"uncommon","id":"string-of-bananas","subtitle":"Trailer","details":"Banana-shaped leaves strung on fast-growing strands; hardier and thirstier than its cousin String of Pearls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Senecio%20radicans-yercaud-salem-India.JPG?width=1024"},{"name":"Hoya shepherdii","rarity":"uncommon","id":"hoya-shepherdii","subtitle":"Hoya","details":"Impossibly long, slender 'string bean' leaves drape from baskets; a slow, elegant oddity among hoyas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya%20shepherdi.jpg?width=1024"},{"name":"Blue Star Fern","rarity":"uncommon","id":"blue-star-fern","subtitle":"Fern","details":"Phlebodium's blue-green, lobed fronds grow from fuzzy golden rhizomes, and it forgives irregular watering better than most ferns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phlebodium%20aureum%20%27Blue%20Star%27%20-%20Longwood%20Gardens%20-%20DSC01161.JPG?width=1024"},{"name":"Crocodile Fern","rarity":"uncommon","id":"crocodile-fern","subtitle":"Fern","details":"Broad fronds are embossed with a network of dark veins that mimics crocodile hide, on a plant that wants steady humidity.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crocodile%20Fern%20%28Microsorum%20musifolium%20%E2%80%98Crocodyllus%E2%80%99%29.jpg?width=1024"},{"name":"Lemon Button Fern","rarity":"uncommon","id":"lemon-button-fern","subtitle":"Fern","details":"Tiny round leaflets line arching stems; rub them and they release a faint lemon scent, a parlour trick since Victorian times.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nephrolepis%20cordifolia%20%27Duffii%27%20kz01.jpg?width=1024"},{"name":"Kimberly Queen Fern","rarity":"uncommon","id":"kimberly-queen-fern","subtitle":"Fern","details":"An upright Australian sword fern with bold, tidy fronds that suit pots and porches, more sun-tolerant than the Boston fern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nephrolepis%20obliterata%20Kimberly%20Queen%202zz.jpg?width=1024"},{"name":"Dancing Lady Orchid","rarity":"uncommon","id":"dancing-lady-orchid","subtitle":"Orchid","details":"Oncidium sprays carry dozens of ruffled yellow blooms that seem to dance; each flower looks like a skirted dancer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yellow%20oncidium%20orchid%20bloom.png?width=1024"},{"name":"Pansy Orchid","rarity":"uncommon","id":"pansy-orchid","subtitle":"Orchid","details":"Miltoniopsis blooms are broad, flat and pansy-faced, often with waterfall patterns, and many are sweetly fragrant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Miltoniopsis%20orchid%20%2849470940026%29.jpg?width=1024"},{"name":"Cymbidium Orchid","rarity":"uncommon","id":"cymbidium-orchid","subtitle":"Orchid","details":"Cool-growing boat orchids send up long spikes of waxy, long-lasting flowers, prized as cut blooms and winter houseplants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cymbidium%20hybrid%201001%20Orchids.jpg?width=1024"},{"name":"Lady Palm","rarity":"uncommon","id":"lady-palm","subtitle":"Palm","details":"Rhapis excelsa fans spread like fingers on bamboo-like canes; it was cultivated in Japan for centuries as a refined parlour palm.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Broadleaf%20Lady%20Palm%20%28Rhapis%20excelsa%29.jpg?width=900"},{"name":"Fishtail Palm","rarity":"uncommon","id":"fishtail-palm","subtitle":"Palm","details":"Caryota leaflets are jagged triangles shaped like fishtails; the whole palm has a fluffy, layered silhouette unlike any other.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fishtail%20Palm%20Caryota%20Mitis%20Clustering%20Fishtail%20Palm%20at%20Garden%20of%20the%20Groves%20Botanical%20Garden%20in%20Grand%20Bahama.jpg?width=1024"},{"name":"Neoregelia","rarity":"uncommon","id":"neoregelia","subtitle":"Bromeliad","details":"At flowering, the flat rosette's heart flushes red or purple while small blooms open in the central cup, like a painted target.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Neoregelia%20macrosepala%20-%20Marie%20Selby%20Botanical%20Gardens%20-%20Sarasota%2C%20Florida%20-%20DSC01684.jpg?width=1024"},{"name":"Vriesea","rarity":"uncommon","id":"vriesea","subtitle":"Bromeliad","details":"Flaming sword bromeliads raise a flattened, sword-like spike of red or yellow bracts above patterned, banded leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vriesea%20splendens%200zz.jpg?width=1024"},{"name":"Spanish Moss","rarity":"uncommon","id":"spanish-moss","subtitle":"Air Plant","details":"Neither Spanish nor a moss: a rootless tillandsia that drapes trees in silver festoons and feeds entirely from air and rain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tillandsia%20usneoides%20kz14.jpg?width=1024"},{"name":"Butterwort","rarity":"uncommon","id":"butterwort","subtitle":"Carnivorous","details":"Pinguicula's greasy, flypaper leaves digest fungus gnats on the windowsill; many kinds also bloom like tiny violets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pinguicula%20vulgaris.JPG?width=1024"},{"name":"Jewel Orchid","rarity":"uncommon","id":"jewel-orchid","subtitle":"Orchid","details":"Ludisia discolor is grown for its leaves, not flowers: velvet-black foliage veined in red-gold pinstripes that sparkle in low light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ludisia%20discolor%204zz.jpg?width=1024"},{"name":"Cat Palm","rarity":"uncommon","id":"cat-palm","subtitle":"Palm","details":"A clustering Mexican palm of many slim stems and lush fronds, sized for tabletops when young and thickets when mature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaedorea%20cataractarum%20kz2.JPG?width=900"},{"name":"Bamboo Palm","rarity":"uncommon","id":"bamboo-palm","subtitle":"Palm","details":"Slender, ringed stems like bamboo carry feathery fronds; it spreads into a soft screen and tolerates dim rooms well.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaedorea%20seifrizii7.jpg?width=1024"},{"name":"Areca Palm","rarity":"uncommon","id":"areca-palm","subtitle":"Palm","details":"Golden cane-like stems and feathery fronds made the areca the classic mall and conservatory palm across the tropics.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dypsis%20lutescens%20%28190109-1051%29.jpg?width=900"},{"name":"Echeveria 'Perle von Nürnberg'","rarity":"uncommon","id":"echeveria-perle-von-n-rnberg","subtitle":"Succulent","details":"A vintage hybrid rosette in dusty lilac-pink, edged with a fine powdery bloom.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20%27Perle%20Von%20N%C3%BCrnberg%27%20leaves.jpg?width=1024"},{"name":"Echeveria 'Black Prince'","rarity":"uncommon","id":"echeveria-black-prince","subtitle":"Succulent","details":"Near-black rosettes with a green heart; the dark prince of the echeveria shelf.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20%27Black%20Prince%27%20-%2020090226.jpg?width=1024"},{"name":"Painted Lady","rarity":"uncommon","id":"painted-lady","subtitle":"Succulent","details":"Blue-green rosettes with red-tipped, keeled leaves; Derenberg's neat little echeveria.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20derenbergii%20-%20JBM.jpg?width=1024"},{"name":"Echeveria 'Topsy Turvy'","rarity":"uncommon","id":"echeveria-topsy-turvy","subtitle":"Succulent","details":"Leaves curl backward like breaking waves, forming a frilled silver-blue rosette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20runyonii%20%27Topsy%20Turvy%27%2C%20Genoa%2C%20Italy%20-%2020060730-01.jpg?width=1024"},{"name":"Jelly Beans","rarity":"uncommon","id":"jelly-beans","subtitle":"Succulent","details":"Plump bean leaves that ripen from green to fiery red tips in bright sun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sedum%20rubrotinctum%207.jpg?width=1024"},{"name":"Ghost Echeveria","rarity":"uncommon","id":"ghost-echeveria","subtitle":"Succulent","details":"Frosty, spoon-shaped leaves stack into a lotus-like rosette of ghostly lilac-white.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20lilacina%2C%20Conservatorio%20bot%C3%A1nico%2C%20Fort%20Wayne%2C%20Indiana%2C%20Estados%20Unidos%2C%202012-11-12%2C%20DD%2001.jpg?width=1024"},{"name":"Flaming Katy","rarity":"uncommon","id":"flaming-katy","subtitle":"Succulent","details":"Clusters of scarlet, pink, and orange stars smother this florist's kalanchoe for months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kalanchoe%20blossfeldiana%20%28Florist%20Kalanchoe%29.jpg?width=1024"},{"name":"Paddle Plant","rarity":"uncommon","id":"paddle-plant","subtitle":"Succulent","details":"Huge round paddles stack and blush crimson at the edges, like a pile of flapjacks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paddle%20Plant%20%28Kalanchoe%20luciae%29%201.jpg?width=1024"},{"name":"Watch Chain","rarity":"uncommon","id":"watch-chain","subtitle":"Succulent","details":"Tiny overlapping leaves zip up branching stems into dense, chain-like green cords.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crassula%20muscosa%20Grubosz%202006-05-03%2001.jpg?width=900"},{"name":"Propeller Plant","rarity":"uncommon","id":"propeller-plant","subtitle":"Succulent","details":"Sickle-shaped grey leaves twist like airplane propellers, topped by scarlet flower clusters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crassula%20perfoliata%20falcata%201zz.jpg?width=1024"},{"name":"Thimble Cactus","rarity":"uncommon","id":"thimble-cactus","subtitle":"Cactus","details":"Clusters of tiny white-spined barrels no bigger than thimbles, offsetting into whole pincushions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E9%8A%80%E6%89%8B%E6%8C%87%2020190409112933.jpg?width=1024"},{"name":"Old Lady Cactus","rarity":"uncommon","id":"old-lady-cactus","subtitle":"Cactus","details":"A round cactus cloaked in white hair and hooked spines, crowned with a ring of pink flowers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mammillaria-hahniana.jpg?width=1024"},{"name":"Domino Cactus","rarity":"uncommon","id":"domino-cactus","subtitle":"Cactus","details":"A dark green globe dotted with neat white areoles and short black spines, like domino spots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echinopsis%20ancistrophora1MW.jpg?width=1024"},{"name":"Easter Cactus","rarity":"uncommon","id":"easter-cactus","subtitle":"Cactus","details":"Rounded, bristle-edged segments welcome spring with starry scarlet and pink blooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hatiora%20gaertneri.jpg?width=1024"},{"name":"Pencil Cactus","rarity":"uncommon","id":"pencil-cactus","subtitle":"Succulent","details":"A thicket of smooth green pencils from a euphorbia; handle with care, its milky sap irritates skin.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Euphorbia%20tirucalli%20Wilczomlecz%202024-02-29%20Graz%2003.jpg?width=1024"},{"name":"Tiger Tooth Aloe","rarity":"uncommon","id":"tiger-tooth-aloe","subtitle":"Succulent","details":"Triangular leaves edged with soft white teeth stack into a fierce little rosette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloe%20juvenna%20kz01.jpg?width=1024"},{"name":"Lace Aloe","rarity":"uncommon","id":"lace-aloe","subtitle":"Succulent","details":"Dark leaves speckled white and edged in delicate lace-like teeth; a tabletop jewel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aloe%20aristata.jpg?width=1024"},{"name":"Fairy Castle Cactus","rarity":"uncommon","id":"fairy-castle-cactus","subtitle":"Cactus","details":"Turrets of columnar stems branch into a miniature castle skyline of spires and towers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acanthocereus%20tetragonus%20Cv.Fairy%20Castle-2-R.M.Nagar-bengaluru-India.jpg?width=1024"},{"name":"Stephanotis","rarity":"uncommon","id":"stephanotis","subtitle":"Flowering","details":"Stephanotis floribunda, the Madagascar jasmine, bears waxy white bridal bouquets of intensely fragrant stars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stephanotis%20floribunda%20variegata%2011.JPG?width=1024"},{"name":"False Shamrock","rarity":"uncommon","id":"false-shamrock","subtitle":"Flowering","details":"Oxalis triangularis folds its purple clover leaves shut at night and reopens them with the morning light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Purple%20shamrock%20%28Oxalis%20triangularis%29%20Maligano%20Buton%20Island%202.jpg?width=1024"},{"name":"Tuberous Begonia","rarity":"uncommon","id":"tuberous-begonia","subtitle":"Flowering","details":"Begonia x tuberhybrida loads summer baskets with rose-like double blooms grown from knobbly tubers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Begonia%20tuberhybrida%200.3%20R.jpg?width=1024"},{"name":"Scented Geranium","rarity":"uncommon","id":"scented-geranium","subtitle":"Flowering","details":"Pelargonium cultivars release rose, lemon or mint perfume from their leaves at the slightest brush of a hand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scented%20geraniums%20are%20for%20lovers.jpg?width=1024"},{"name":"Primrose","rarity":"uncommon","id":"primrose","subtitle":"Flowering","details":"Primula obconica and its kin bring jewel-bright winter colour to cool windowsills when little else blooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Primula%20obconica2.jpg?width=1024"},{"name":"Gloxinia","rarity":"uncommon","id":"gloxinia","subtitle":"Flowering","details":"Sinningia speciosa opens velvet bell flowers so rich in colour they look hand-painted, then rests as a tuber.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gloxinia%20-%20%28Sinningia%20speciosa%29.jpg?width=1024"},{"name":"Cape Primrose","rarity":"uncommon","id":"cape-primrose","subtitle":"Flowering","details":"Streptocarpus blooms for months from a rosette of quilted leaves and tolerates the odd missed watering.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Streptocarpus%20primulifolius%2C%20blomme%2C%20Walter%20Sisulu%20NBT%2C%20a.jpg?width=1024"},{"name":"Yucca Cane","rarity":"uncommon","id":"yucca-cane","subtitle":"Tree","details":"Yucca elephantipes grows as a sturdy indoor cane topped with a rosette of stiff, spineless green swords.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yucca%20elephantipes%20HRM2.JPG?width=1024"},{"name":"Coffee Plant","rarity":"uncommon","id":"coffee-plant","subtitle":"Tree","details":"Coffea arabica makes a glossy indoor shrub; patient growers may see fragrant white blooms and red cherries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coffea%20arabica%20elliptic%20leaves.jpg?width=1024"},{"name":"Dwarf Banana","rarity":"uncommon","id":"dwarf-banana","subtitle":"Tree","details":"Compact Musa cultivars bring instant tropics indoors, unrolling huge paddle leaves at startling speed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr-140614-4555-Musa%20acuminata-Dwarf%20Cuban%20Red%20fruit-Hawea%20Pl%20Olinda-Maui%20%2825243151265%29.jpg?width=900"},{"name":"Root Rot","rarity":"uncommon","id":"root-rot","subtitle":"Care","details":"Soggy soil starves roots of oxygen and invites rot; black, mushy roots and a sour smell are the tell-tale signs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Root%20rot%20in%20cicer%20arietinum%20%28hydro-grown%29.jpg?width=1024"},{"name":"Spider Mites","rarity":"uncommon","id":"spider-mites","subtitle":"Pest","details":"Near-microscopic mites stipple leaves pale and spin fine webbing; they thrive in hot, dry indoor air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tetranychus%20urticae%20with%20silk%20threads.jpg?width=1024"},{"name":"Mealybugs","rarity":"uncommon","id":"mealybugs","subtitle":"Pest","details":"These white cottony sap-suckers cluster in leaf joints and hide under leaves, raining sticky honeydew below.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr-130914-1508-Ipomoea%20pes%20caprae%20subsp%20brasiliensis-leaf%20with%20whitefly%20or%20mealybug-Near%20lake-Laysan%20%2825224992515%29.jpg?width=1024"},{"name":"Water Propagation","rarity":"uncommon","id":"water-propagation","subtitle":"Propagation","details":"Cut stems root readily in a jar of water on the sill, letting growers watch new roots form day by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ficus%20cuttings%20with%20roots%20in%20a%20bottle%2C%20White%20background.jpg?width=1024"},{"name":"Moss Pole","rarity":"uncommon","id":"moss-pole","subtitle":"Care","details":"A moss or coir pole gives climbing plants' aerial roots something to grip, rewarding them with larger leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20growing%20into%20coir%20pole.jpg?width=1024"},{"name":"Grow Light","rarity":"uncommon","id":"grow-light","subtitle":"Care","details":"Full-spectrum lamps stand in for the sun through dark winters, keeping light-hungry plants compact and coloured.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/An%20HPS%20grow%20light%20in%20grow%20tent%2C%20with%20carbon%20filter%20and%20exhaust%20system.jpg?width=1024"},{"name":"Closed Terrarium","rarity":"uncommon","id":"closed-terrarium","subtitle":"Terrarium","details":"Sealed under glass, a closed terrarium rains on itself: moisture condenses, drips back and waters the plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sealed%20terrarium.jpg?width=1024"},{"name":"Victorian Fern Craze","rarity":"uncommon","id":"victorian-fern-craze","subtitle":"Lore","details":"Pteridomania swept Victorian Britain; fern hunters and parlour fern cases turned houseplants into a fashion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Benmore%20Fernery%2C%20Dunoon%2C%20Argyll.%20Internal%20view.jpg?width=1024"},{"name":"Monstera borsigiana","rarity":"common","id":"monstera-borsigiana","subtitle":"Aroid","details":"The fast, compact form of deliciosa long sold in garden centres, with slightly smaller, quicker leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20deliciosa%20Monstera%20dziurawa%202023-10-31%2004.jpg?width=1024"},{"name":"Monstera obliqua","rarity":"common","id":"monstera-obliqua","subtitle":"Aroid","details":"Famed as more hole than leaf; true obliqua is vanishingly rare in trade, where most plants sold as it are adansonii.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monstera%20obliqua.jpg?width=1024"},{"name":"Monstera acuminata","rarity":"common","id":"monstera-acuminata","subtitle":"Aroid","details":"A climbing Monstera whose oval leaves are pierced by neat rows of holes; often confused with its adansonii cousin.","image":"https://inaturalist-open-data.s3.amazonaws.com/photos/335349658/large.jpg"},{"name":"Rhaphidophora decursiva","rarity":"common","id":"rhaphidophora-decursiva","subtitle":"Aroid","details":"The dragon tail plant: a shingling juvenile that matures into huge, split palm-like leaves up a pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Raphidophora%20decursiva.jpg?width=900"},{"name":"Rhaphidophora hayi","rarity":"common","id":"rhaphidophora-hayi","subtitle":"Aroid","details":"A shingle plant hugging boards and bark with neat rows of overlapping, coin-like green leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhaphidophora%20hayi-2-LRI%20layout-bengaluru-India.jpg?width=1024"},{"name":"Rhaphidophora cryptantha","rarity":"common","id":"rhaphidophora-cryptantha","subtitle":"Aroid","details":"Tiny shingling leaves with silver veins form a living mosaic flat against bark, cork or a terrarium wall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rhaphidophora%20cryptantha%20P4218402.jpg?width=1024"},{"name":"Philodendron bipinnatifidum","rarity":"common","id":"philodendron-bipinnatifidum","subtitle":"Aroid","details":"The selloum: a self-heading giant whose deeply lobed leaves build a tropical fountain of green.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20bipinnatifidum%206zz.jpg?width=900"},{"name":"Philodendron 'Xanadu'","rarity":"common","id":"philodendron-xanadu","subtitle":"Cultivar","details":"A compact, self-heading plant with glossy, deeply lobed leaves; bred in Australia and grown everywhere.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20Xanadu%200zz.jpg?width=1024"},{"name":"Philodendron 'Rojo Congo'","rarity":"common","id":"philodendron-rojo-congo","subtitle":"Cultivar","details":"Thick copper-red new leaves darken to deep green on burgundy stems; a sturdy, upright floor plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20Rojo%20Congo%202zz.jpg?width=1024"},{"name":"Philodendron 'Prince of Orange'","rarity":"common","id":"philodendron-prince-of-orange","subtitle":"Cultivar","details":"New leaves unfurl bright orange, ripening through copper and chartreuse to green as they age.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20Prince%20of%20Orange%203zz.jpg?width=1024"},{"name":"Philodendron 'McColley's Finale'","rarity":"common","id":"philodendron-mccolleys-finale","subtitle":"Cultivar","details":"Cinnamon-red new growth settles to glossy deep green; a compact hybrid with a warm colour show.","image":"https://cdn.shopify.com/s/files/1/0538/7583/5073/files/philodendron-mccolley-s-finale-root-houseplants-21994_560x680_crop_center.jpg"},{"name":"Philodendron 'Moonlight'","rarity":"common","id":"philodendron-moonlight","subtitle":"Cultivar","details":"A self-heading plant whose new leaves glow chartreuse-yellow before softening to fresh green.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20Moonlight%201zz.jpg?width=1024"},{"name":"Philodendron 'Painted Lady'","rarity":"common","id":"philodendron-painted-lady","subtitle":"Cultivar","details":"Chartreuse leaves mottled with green, held on blush-pink stems; colour deepens as it climbs a pole.","image":"https://live.staticflickr.com/65535/51881908704_bb7106eca5_b.jpg"},{"name":"Philodendron hederaceum","rarity":"common","id":"philodendron-hederaceum","subtitle":"Aroid","details":"The classic heart-leaf Philodendron: glossy green hearts trailing from generations of windowsills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20hederaceum%2C%20Singapore%20Botanic%20Gardens%20%28141542%29.jpg?width=900"},{"name":"Philodendron cordatum","rarity":"common","id":"philodendron-cordatum","subtitle":"Aroid","details":"A true species with velvety, elongated heart leaves, often confused with the common heart-leaf hederaceum.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr-090617-0989-Philodendron%20cordatum-habit-Huelo-Maui%20%2824871975801%29.jpg?width=900"},{"name":"Philodendron hastatum","rarity":"common","id":"philodendron-hastatum","subtitle":"Aroid","details":"The silver sword: metallic blue-grey, spear-shaped leaves on a climbing stem, unlike any other in the genus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20hastatum-2-Vishuddhi%20garden-bengaluru-India.jpg?width=1024"},{"name":"Philodendron burle-marxii","rarity":"common","id":"philodendron-burle-marxii","subtitle":"Aroid","details":"A scrambling, easy species with glossy arrow leaves, named for landscape architect Roberto Burle Marx.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20burle-marxii.jpg?width=1024"},{"name":"Philodendron goeldii","rarity":"common","id":"philodendron-goeldii","subtitle":"Aroid","details":"Leaves split into a ring of fingers like a green hand; now classed in Thaumatophyllum but sold as Philodendron.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20goeldii%20BotGardBln07122011L.JPG?width=1024"},{"name":"Philodendron 'Royal Queen'","rarity":"common","id":"philodendron-royal-queen","subtitle":"Cultivar","details":"Deep burgundy-black new leaves mature to dark green on wine-red stems; a compact, moody hybrid.","image":"https://cdn.shopify.com/s/files/1/0284/2450/products/PhilodendronRoyalQueen-1.jpg"},{"name":"Philodendron erubescens","rarity":"common","id":"philodendron-erubescens","subtitle":"Aroid","details":"The blushing Philodendron, parent of 'Pink Princess': arrow leaves with red undersides on red stems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Philodendron%20erubescens%20Plant.jpg?width=1024"},{"name":"Syngonium podophyllum","rarity":"common","id":"syngonium-podophyllum","subtitle":"Aroid","details":"The Arrowhead Plant: fast, forgiving, and happy trailing or climbing a moss pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr-110218-1635-Syngonium%20podophyllum-habit-Ulana%20St%20Makawao-Maui%20%2824781034340%29.jpg?width=1024"},{"name":"Cast Iron Plant","rarity":"common","id":"cast-iron-plant","subtitle":"Foliage","details":"A Victorian parlour survivor with broad, leathery leaves; famously unbothered by low light, drought and neglect.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aspidistra%2001%20%28fcm%29.jpg?width=1024"},{"name":"Dieffenbachia seguine","rarity":"common","id":"dieffenbachia-seguine","subtitle":"Aroid","details":"The classic Dumb Cane, grown since Victorian times; its sap silences, so keep it from pets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dieffenbachia%20seguine%20kz08.jpg?width=1024"},{"name":"Dieffenbachia 'Tropic Snow'","rarity":"common","id":"dieffenbachia-tropic-snow","subtitle":"Cultivar","details":"Big leaves splashed generously with cream and white; one of the oldest dieffenbachia cultivars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dieffenbachia%20amoena%20tropic%20snow-1-anna%20park-yercaud-salem-India.JPG?width=1024"},{"name":"Aglaonema commutatum","rarity":"common","id":"aglaonema-commutatum","subtitle":"Aroid","details":"The species behind most Chinese evergreens: lance leaves patterned in silver-green.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aglaonema%20commutatum%20%28poison%20dart%20plant%29.jpg?width=1024"},{"name":"Aglaonema 'Maria'","rarity":"common","id":"aglaonema-maria","subtitle":"Cultivar","details":"Deep green leaves marbled with silver; thrives where fussier plants give up.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aglaonema%20Maria%20Christina%202zz.jpg?width=1024"},{"name":"Aglaonema 'Red Siam'","rarity":"common","id":"aglaonema-red-siam","subtitle":"Cultivar","details":"Green leaves edged and veined in red; the Siam Aurora type brings colour to dim rooms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aglaonema%20siam%20aurora-1-bsi-yercaud-salem-India.jpg?width=1024"},{"name":"Caladium bicolor","rarity":"common","id":"caladium-bicolor","subtitle":"Aroid","details":"The species behind fancy-leaf caladiums, grown from tubers for paper-thin summer leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caladium%20bicolor%20%2811137872774%29.jpg?width=1024"},{"name":"Caladium 'Miss Muffet'","rarity":"common","id":"caladium-miss-muffet","subtitle":"Cultivar","details":"A dwarf caladium: lime-green leaves freckled with deep pink spots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caladium%20%27Miss%20Moffet%27%20-%20Chelsea%20Flower%20Show%202024%20-%20DSC02605.jpg?width=1024"},{"name":"Calathea lancifolia","rarity":"common","id":"calathea-lancifolia","subtitle":"Prayer Plant","details":"The Rattlesnake Plant: wavy lance leaves patterned with dark ovals, purple beneath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calathea%20lancifolia%20-%20rattlesnake%20plant%20-%20from-DC1.jpg?width=1024"},{"name":"Calathea ornata","rarity":"common","id":"calathea-ornata","subtitle":"Prayer Plant","details":"The Pinstripe Plant: dark leaves ruled with fine pink-white lines like notebook paper.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CalatheaOrnataRoseo-Lineata.jpg?width=1024"},{"name":"Calathea zebrina","rarity":"common","id":"calathea-zebrina","subtitle":"Prayer Plant","details":"Velvet leaves striped like a zebra in two greens, with rich purple undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zebra%20Plant%20%28Calathea%20Zebrina%29.jpg?width=1024"},{"name":"Maranta leuconeura","rarity":"common","id":"maranta-leuconeura","subtitle":"Prayer Plant","details":"The Prayer Plant itself: leaves fold up at night, showing red veins and purple undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maranta%20leuconeura%2011zz.jpg?width=1024"},{"name":"Fatsia japonica","rarity":"common","id":"fatsia-japonica","subtitle":"Foliage","details":"Huge glossy palmate leaves give instant jungle; a Victorian parlour favourite reborn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fatsia%20japonica.003%20-%20Zapateira.jpg?width=1024"},{"name":"Schefflera arboricola","rarity":"common","id":"schefflera-arboricola","subtitle":"Foliage","details":"The Dwarf Umbrella Tree: glossy leaflets radiate like umbrella spokes from each stem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heptapleurum%20arboricola%20Szeflera%20drzewkowata%202024-01-19%20Malaga%2002.jpg?width=1024"},{"name":"False Aralia","rarity":"common","id":"false-aralia","subtitle":"Foliage","details":"A lacy, dark-green small tree whose finely divided, serrated leaflets give it a delicate, fern-like silhouette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dizygotheca%20elegantissima%20%2812%29.jpg?width=1024"},{"name":"Dracaena 'Lemon Lime'","rarity":"common","id":"dracaena-lemon-lime","subtitle":"Foliage","details":"A cane dracaena striped in lemon yellow and lime green; one of the brightest foliage plants for a dull corner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr-080117-1535-Dracaena%20fragrans-Lemon%20Lime%20leaves-Walmart%20Kahului-Maui%20%2824604641960%29.jpg?width=1024"},{"name":"Dracaena fragrans 'Janet Craig'","rarity":"common","id":"dracaena-fragrans-janet-craig","subtitle":"Cultivar","details":"Glossy dark-green strap leaves on a cane; a corporate-lobby legend for surviving anything.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dracaena%20Deremensis%20Janet%20Craig%20Flowering.jpg?width=1024"},{"name":"Dracaena reflexa 'Song of India'","rarity":"common","id":"dracaena-reflexa-song-of-india","subtitle":"Cultivar","details":"Narrow leaves striped gold and green on branching stems, bright as a woven ribbon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dracaena%20reflexa%20%27Song%20of%20India%27%20%28181229-1727%29.jpg?width=1024"},{"name":"Codiaeum variegatum","rarity":"common","id":"codiaeum-variegatum","subtitle":"Foliage","details":"The Croton: leathery leaves painted in red, orange, and gold, brightest in strong light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Croton%20%28Codiaeum%20variegatum%29%2C%20jard%C3%ADn%20bot%C3%A1nico%20de%20Tallinn%2C%20Estonia%2C%202012-08-13%2C%20DD%2001.JPG?width=1024"},{"name":"Hoya curtisii","rarity":"common","id":"hoya-curtisii","subtitle":"Hoya","details":"A miniature trailer: tiny speckled silver-mottled leaves form a dense mat spilling over small pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_curtisii.jpg?width=1024"},{"name":"Hoya serpens","rarity":"common","id":"hoya-serpens","subtitle":"Hoya","details":"Small round fuzzy leaves creep flat against mounts and terrarium walls, rooting as they wander.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_serpens_kz01.jpg?width=1024"},{"name":"Red Log Peperomia","rarity":"common","id":"red-log-peperomia","subtitle":"Peperomia","details":"Whorled spoon-shaped leaves stack up its stems, green above and glowing burgundy beneath like polished mahogany.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia%20verticillata%20%27Red%20Log%27%20kz02.jpg?width=1024"},{"name":"Peperomia scandens","rarity":"common","id":"peperomia-scandens","subtitle":"Peperomia","details":"The cupid peperomia: heart-shaped leaves on pink-tinged trailing stems, an easy basket filler.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia%20serpens%202011-01-17.jpg?width=1024"},{"name":"Inchplant","rarity":"common","id":"inchplant","subtitle":"Trailer","details":"Tradescantia fluminensis races along at an inch a week in good light, rooting wherever a node touches soil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tradescantia_fluminensis_leaf3_%2815754515524%29.jpg?width=1024"},{"name":"Tradescantia fluminensis 'Variegata'","rarity":"common","id":"tradescantia-fluminensis-variegata","subtitle":"Cultivar","details":"Cream-and-pink striped inchplant, brighter and slower than its green parent, for sunlit shelves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tradescantia_fluminensis_variegata-1-xavier_cottage-yercaud-salem-India.JPG?width=1024"},{"name":"Hoya callistophylla","rarity":"common","id":"hoya-callistophylla","subtitle":"Hoya","details":"Bold leaves etched with dark green veins like stained glass, prized by collectors of dramatic foliage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya_callistophylla_T.Green_in_Fraterna_13%284%29-_2_%282000%29_20260205_104854.jpg?width=1024"},{"name":"Shooting Star Hoya","rarity":"common","id":"shooting-star-hoya","subtitle":"Hoya","details":"Hoya multiflora fires off reflexed white-and-yellow blooms like a burst of shooting stars, again and again.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shooting%20Stars%20%28Hoya%20multiflora%29.jpg?width=1024"},{"name":"Peperomia rotundifolia","rarity":"common","id":"peperomia-rotundifolia","subtitle":"Peperomia","details":"Tiny round leaves on thread stems trail like green bead curtains in its South American rainforest home.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_rotundifolia_var._rotundifolia_kz01.jpg?width=1024"},{"name":"Prayer Pepper","rarity":"common","id":"prayer-pepper","subtitle":"Peperomia","details":"Peperomia dolabriformis folds each leaf into a plump half-moon 'taco', a succulent oddity from Peru.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_dolabriformis.jpg?width=1024"},{"name":"Million Hearts","rarity":"common","id":"million-hearts","subtitle":"Trailer","details":"Dischidia ruscifolia packs hundreds of tiny heart leaves along fine vines that cling and cascade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dischidia_ruscifolia_kz05.jpg?width=1024"},{"name":"Watermelon Dischidia","rarity":"common","id":"watermelon-dischidia","subtitle":"Trailer","details":"Oval leaves streaked like watermelon rind trail from this epiphyte, often grown on bark mounts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dischidia_ovata_kz1.jpg?width=1024"},{"name":"Kangaroo Vine","rarity":"common","id":"kangaroo-vine","subtitle":"Vine","details":"A tough Australian climber with glossy toothed leaves, happy scrambling up a moss pole or trellis.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cissus%20antarctica%20kz1.JPG?width=1024"},{"name":"Turtle Vine","rarity":"common","id":"turtle-vine","subtitle":"Trailer","details":"Callisia repens carpets pots with tiny green-and-purple leaves, then cascades over the edge in mats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Callisia_repens_in_Bangkok.jpg?width=1024"},{"name":"Callisia repens 'Pink Lady'","rarity":"common","id":"callisia-repens-pink-lady","subtitle":"Cultivar","details":"A blushing turtle vine: miniature leaves striped cream, pink, and green in strong light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Callisia_Repens_%27Pink_Panther%27.jpg?width=1024"},{"name":"White Velvet","rarity":"common","id":"white-velvet","subtitle":"Trailer","details":"Tradescantia sillamontana wears a cobweb of white hairs over olive leaves, armour against its Mexican sun.","image":"https://upload.wikimedia.org/wikipedia/commons/0/04/Tradescantia_sillamontana.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Hoya diversifolia","rarity":"common","id":"hoya-diversifolia","subtitle":"Hoya","details":"A variable, vigorous climber whose leaf shape shifts from plant to plant, true to its 'diverse leaves' name.","image":"https://upload.wikimedia.org/wikipedia/commons/6/61/Hoya_diversifolia1NatureAtYourBackyard.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Peperomia nivalis","rarity":"common","id":"peperomia-nivalis","subtitle":"Peperomia","details":"Boat-shaped leaves fold upward with a pale window stripe, a tiny succulent sculpture from Peru.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia%20nivalis%20-%20Botanischer%20Garten%20M%C3%BCnchen-Nymphenburg%20-%20DSC08109.JPG?width=900"},{"name":"Column Peperomia","rarity":"common","id":"column-peperomia","subtitle":"Peperomia","details":"Peperomia columella stacks thick windowed leaves up a short column like a tiny green totem pole.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_columella_01.jpg?width=1024"},{"name":"Felted Peperomia","rarity":"common","id":"felted-peperomia","subtitle":"Peperomia","details":"Soft white felt coats every leaf of Peperomia incana, a Brazilian species that begs to be stroked.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia%20incana%200zz.jpg?width=1024"},{"name":"Peperomia clusiifolia 'Rainbow'","rarity":"common","id":"peperomia-clusiifolia-rainbow","subtitle":"Cultivar","details":"The rainbow jelly plant: thick leaves edged in cream, pink, and red like a slow-growing sunset.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peperomia_clusiifolia_variegata-1-bsi-yercaud-salem-India.JPG?width=1024"},{"name":"Hoya pachyclada","rarity":"common","id":"hoya-pachyclada","subtitle":"Hoya","details":"Thick, rounded leaves on stout stems and tight umbels of white stars with pink hearts; a slow, sculptural hoya.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hoya%20pachyclada%202024.jpg?width=1024"},{"name":"String of Spades","rarity":"common","id":"string-of-spades","subtitle":"Trailer","details":"The spade-leaf form of String of Hearts trails silver-flecked blades instead of rounded hearts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ceropegia_woodii_Silver_Glory_2020-06-07_9407.jpg?width=1024"},{"name":"Hedera helix 'Glacier'","rarity":"common","id":"hedera-helix-glacier","subtitle":"Cultivar","details":"A frost-edged English ivy: grey-green leaves rimmed in cream, crisp as winter light in a cool room.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hedera_helix_%27Glacier%27_kz01.jpg?width=1024"},{"name":"Macho Fern","rarity":"common","id":"macho-fern","subtitle":"Fern","details":"A giant sword fern with fronds up to two metres long, grown in big baskets where its bold texture can sprawl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20Sword%20Fern%20%28Nephrolepis%20biserrata%29%201.jpg?width=900"},{"name":"Holly Fern","rarity":"common","id":"holly-fern","subtitle":"Fern","details":"Cyrtomium's glossy, leathery leaflets mimic holly leaves, and it shrugs off dry indoor air better than delicate ferns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cyrtomium%20falcatum%20Cyrtomium%20sierpowate%202023-10-31%2003.jpg?width=1024"},{"name":"Ribbon Fern","rarity":"common","id":"ribbon-fern","subtitle":"Fern","details":"Pteris cretica fronds pair narrow fertile pinnae with broader sterile ones; variegated forms carry a cream central stripe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pteris%20cretica%201.jpg?width=1024"},{"name":"Button Fern","rarity":"common","id":"button-fern","subtitle":"Fern","details":"Pellaea rotundifolia trails neat stems of round, dark-green buttons, happy in a hanging pot in bright, indirect light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pellaea%20rotundifolia%20-%20Fern%20House%20-%20Christchurch%20Botanic%20Gardens%20-%20Christchurch%2C%20NZ%20-%20DSC00591.jpg?width=1024"},{"name":"Peacock Fern","rarity":"common","id":"peacock-fern","subtitle":"Fern","details":"Selaginella willdenowii climbs and shimmers iridescent blue-green, the colour shifting with light angle like a peacock feather.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peacock%20fern%20Selaginella%20willdenowii.jpg?width=900"},{"name":"Frosty Fern","rarity":"common","id":"frosty-fern","subtitle":"Fern","details":"A selaginella moss fern sold at the holidays, its lacy, fern-like sprays tipped white as if dusted with frost.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Selaginella%20kraussiana%20%27Aurea%27%20kz01.jpg?width=1024"},{"name":"Korean Rock Fern","rarity":"common","id":"korean-rock-fern","subtitle":"Fern","details":"A compact Korean holly fern relative with glossy, finely cut fronds, sold for terrariums and small pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Polystichum%20tsus-simense%20frond.jpg?width=1024"},{"name":"Fluffy Ruffles Fern","rarity":"common","id":"fluffy-ruffles-fern","subtitle":"Fern","details":"A dwarf Boston fern mutation packed with tiny, crested, ruffled leaflets, forming a dense cushion in small pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nephrolepis%20exaltata%20Fluffy%20Ruffles%200zz.jpg?width=1024"},{"name":"European Fan Palm","rarity":"common","id":"european-fan-palm","subtitle":"Palm","details":"The only palm native to Europe, a clumping fan palm hardy enough for conservatories and bright rooms with cool winters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chamaerops%20humilis%20%28Zingaro%29015.jpg?width=1024"},{"name":"Brassia Orchid","rarity":"common","id":"brassia-orchid","subtitle":"Orchid","details":"Spider orchids earned their name: long, spidery petals on arching sprays, often spotted and sweetly scented by day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brassia%20gireoudiana%20flowers.jpg?width=900"},{"name":"Encyclia Orchid","rarity":"common","id":"encyclia-orchid","subtitle":"Orchid","details":"Upside-down blooms nod from Encyclia spikes, the lip on top; many smell of vanilla, chocolate or citrus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prosthechea%20cochleata%20Encyclia%20cochleata%20OrchidsBln0906c.jpg?width=1024"},{"name":"Lightning Jewel Orchid","rarity":"common","id":"lightning-jewel-orchid","subtitle":"Orchid","details":"Macodes petola's velvet leaves are netted with gold veins that glitter like lightning, a terrarium jewel from Malaysia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20and%20B%20Larsen%20orchids%20-%20Macodes%20petola%20836-16.jpg?width=900"},{"name":"Medusa Air Plant","rarity":"common","id":"medusa-air-plant","subtitle":"Air Plant","details":"Tillandsia caput-medusae grows a swollen, bulb-like base and snaking, Medusa-hair leaves; ants often colonise it in the wild.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tillandsia%20caput-medusae%20-%20desc-flower%20tangle%20-%20from-DC1%20-%20stat-vulnerable.jpg?width=1024"},{"name":"Bulbosa Air Plant","rarity":"common","id":"bulbosa-air-plant","subtitle":"Air Plant","details":"A squid-like air plant with a bulbous base and wavy tentacle leaves, blushing red before its purple tubular flowers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tillandsia%20bulbosa%2020090111.jpg?width=1024"},{"name":"Pink Quill","rarity":"common","id":"pink-quill","subtitle":"Bromeliad","details":"Tillandsia cyanea raises a flat pink paddle — the quill — from which violet flowers emerge one by one over weeks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Wallisia%20cyanea%2C%20Longwood%20Gardens%202024%2001.jpg?width=1024"},{"name":"Earth Star","rarity":"common","id":"earth-star","subtitle":"Bromeliad","details":"Cryptanthus rosettes hug the ground in wavy, banded stars of pink, silver and green, made for terrariums and shallow bowls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/210820%20030%20SD%20Botanic%20Garden%20-%20Dickinson%20Family%20Conservatory%2C%20World%20of%20Bromeliads%2C%20Cryptanthus%20zonatus%20cv.jpg?width=1024"},{"name":"Queen's Tears","rarity":"common","id":"queens-tears","subtitle":"Bromeliad","details":"Billbergia nutans dangles pink-bracted blooms that weep drops of nectar — the 'queen's tears' — and offsets freely.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Billbergia%20Nutans%20Bromeliad.jpg?width=1024"},{"name":"Bladderwort","rarity":"common","id":"bladderwort","subtitle":"Carnivorous","details":"Utricularia hunts underwater and in wet soil with tiny suction bladders that snap open in milliseconds; its flowers mimic orchids.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Utricularia%20vulgaris%20kz04.jpg?width=1024"},{"name":"Heart Fern","rarity":"common","id":"heart-fern","subtitle":"Fern","details":"Hemionitis arifolia bears heart-shaped leaves on black stems and even buds baby plantlets from its leaf stalks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hemionitis%20arifolia%20-%20Lyman%20Plant%20House%2C%20Smith%20College%20-%20DSC04278.JPG?width=1024"},{"name":"Aeranthos Air Plant","rarity":"common","id":"aeranthos-air-plant","subtitle":"Air Plant","details":"Tillandsia aeranthos forms tidy clumps of stiff silver leaves and blooms pink and purple, a beginner-friendly air plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tillandsia%20aeranthos.jpg?width=1024"},{"name":"Silver Torch Bromeliad","rarity":"common","id":"silver-torch-bromeliad","subtitle":"Bromeliad","details":"Billbergia pyramidalis, the flaming torch, fires up a short, brilliant red torch of blooms from a vase of plain green leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Billbergia%20pyramidalis%20flower.jpg?width=1024"},{"name":"Snake Plant 'Moonshine'","rarity":"common","id":"snake-plant-moonshine","subtitle":"Succulent","details":"Broad leaves washed in silvery moonlight green, paling almost to white in bright light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sansevieria%20trifasciata%20%27Moonshine%27.jpg?width=1024"},{"name":"African Spear","rarity":"common","id":"african-spear","subtitle":"Succulent","details":"Rigid cylindrical leaves fan upward like a fistful of green spears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sansevieria%20cylindrica%20flowers%202.jpg?width=1024"},{"name":"Snake Plant 'Whale Fin'","rarity":"common","id":"snake-plant-whale-fin","subtitle":"Succulent","details":"One enormous paddle leaf, wide and mottled like a whale's fin rising from the pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mason%27s%20Congo%20Sansevieria%20%28Sansevieria%20masoniana%29%201.jpg?width=1024"},{"name":"Echeveria imbricata","rarity":"common","id":"echeveria-imbricata","subtitle":"Succulent","details":"Blue rosettes with rose-kissed edges form tight, overlapping carpets of offsets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20Imbricata.jpg?width=1024"},{"name":"Echeveria pulidonis","rarity":"common","id":"echeveria-pulidonis","subtitle":"Succulent","details":"Pale blue-green leaves outlined in fine red thread; a slow, tidy rosette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20pulidonis%204.jpg?width=1024"},{"name":"Echeveria setosa","rarity":"common","id":"echeveria-setosa","subtitle":"Succulent","details":"The firecracker plant: rosettes furred in fine white hairs, with red-and-yellow torch flowers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria%20setosaCRH.JPG?width=1024"},{"name":"Echeveria 'Afterglow'","rarity":"common","id":"echeveria-afterglow","subtitle":"Succulent","details":"Wide lavender-pink leaves with glowing hot-pink edges form a rosette the size of a dinner plate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Echeveria-afterglow.jpg?width=1024"},{"name":"Haworthia cooperi","rarity":"common","id":"haworthia-cooperi","subtitle":"Succulent","details":"Translucent, bead-like leaf tips glow like tiny windows when backlit by the sun.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haworthia%20cooperi%20kz01.jpg?width=1024"},{"name":"Haworthia retusa","rarity":"common","id":"haworthia-retusa","subtitle":"Succulent","details":"Star rosettes of thick, window-topped leaves sit flush and flat in the pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2%20Haworthia%20retusa%20-%20Acilliers%20-%20RSA%201.jpg?width=1024"},{"name":"Fairies Washboard","rarity":"common","id":"fairies-washboard","subtitle":"Succulent","details":"Narrow dark leaves carry raised white bands on both sides, ribbed like a tiny washboard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Haworthiopsis%20limifolia%20var.%20limifolia%20f.%20spiralis.jpg?width=1024"},{"name":"Gasteria 'Little Warty'","rarity":"common","id":"gasteria-little-warty","subtitle":"Succulent","details":"Stubby strap leaves rough with white warts, stacking into a tough little fan.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gasteria%20Little%20Warty-2-R.M.Nagar-bengaluru-India.jpg?width=1024"},{"name":"Crassula 'Gollum'","rarity":"common","id":"crassula-gollum","subtitle":"Succulent","details":"Tubular leaves with suction-cup tips grow into a gnarled bonsai shrub straight from Middle-earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crassula%20ovata%20%27Gollum%27%20WA%C5%81BRZYCH-PALMIARNIA%2C%20AB-059.jpg?width=1024"},{"name":"Campfire Crassula","rarity":"common","id":"campfire-crassula","subtitle":"Succulent","details":"Propeller leaves ignite from green to blazing red as the sun and cold bite.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crassula%20capitella%202%20edit.jpg?width=1024"},{"name":"Golden Sedum","rarity":"common","id":"golden-sedum","subtitle":"Succulent","details":"Needle leaves in acid yellow-green mound and spill cheerfully over pot rims.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sedum%20nussbaumerianum%20Madagascar01.jpg?width=1024"},{"name":"Baby Burro's Tail","rarity":"common","id":"baby-burros-tail","subtitle":"Succulent","details":"Shorter, tighter braids of plump leaves than its famous cousin, made for small hanging pots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sedum%20morganianum%20%27Burrito%27%20c-3098%20-%2002.jpg?width=1024"},{"name":"Moonstones","rarity":"common","id":"moonstones","subtitle":"Succulent","details":"Smooth pastel pebbles of pink, lilac, and blue stack loosely along short stems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20260317%20Pachyphytum%20oviferum%2001.jpg?width=1024"},{"name":"Split Rock","rarity":"common","id":"split-rock","subtitle":"Succulent","details":"A single pair of stone-mimic leaves splits down the middle to release a bright flower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aizoaceae%20-%20Pleiospilos%20nelii.JPG?width=1024"},{"name":"Baby Toes","rarity":"common","id":"baby-toes","subtitle":"Succulent","details":"Clusters of tiny green toes, each with a clear window on top to let the light in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fenestraria%20rhopalophylla.jpg?width=1024"},{"name":"Tiger Jaws","rarity":"common","id":"tiger-jaws","subtitle":"Succulent","details":"Triangular leaves lined with soft spines gape like a tiger's jaw, then bloom yellow at noon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Faucaria%20tigrina%20Bl%C3%BCte%20006.png?width=1024"},{"name":"Blue Columnar Cactus","rarity":"common","id":"blue-columnar-cactus","subtitle":"Cactus","details":"Powder-blue columns rise straight and tall, a desert skyscraper for the patio pot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pilosocereus%20pachycladus%202019-07-12%2002.jpg?width=1024"},{"name":"Rat Tail Cactus","rarity":"common","id":"rat-tail-cactus","subtitle":"Cactus","details":"Long, golden-spined tails spill from hanging baskets and bloom magenta in spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aporocactus%20flagelliformis%20K%C3%A4%C3%A4rmekaktus%20Ormkaktus%20IM5678%20C.JPG?width=1024"},{"name":"Ladyfinger Cactus","rarity":"common","id":"ladyfinger-cactus","subtitle":"Cactus","details":"Slim golden fingers cluster and lean together, flowering in soft cream and pink.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Warzenkaktus%20-%20Mammillaria%20elongata.JPG?width=1024"},{"name":"Crinkle Leaf Plant","rarity":"common","id":"crinkle-leaf-plant","subtitle":"Succulent","details":"Wrinkled, almond-shaped leaves with rippled edges stack into an odd, sculptural rosette.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adromischus%20cristatus%20-%20Gaiser%20Conservatory%20%28Manito%20Park%29%20-%20IMG%207008.JPG?width=900"},{"name":"Basil","rarity":"common","id":"basil","subtitle":"Herb","details":"Sweet basil rules the windowsill herb garden but blackens at a hint of frost and hates wet leaves at night.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ocimum%20basilicum%20flowers%20in%20Crimea.jpg?width=1024"},{"name":"Mint","rarity":"common","id":"mint","subtitle":"Herb","details":"Mentha spreads so eagerly by runners that wise growers banish it to a pot of its own on the windowsill.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Corn%20Mint%20%28Mentha%20arvensis%29.jpg?width=1024"},{"name":"Rosemary","rarity":"common","id":"rosemary","subtitle":"Herb","details":"Salvia rosmarinus brings pine-scented needles indoors but demands sharp drainage and strong light to thrive.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rosmarinus%20officinalis133095382.jpg?width=1024"},{"name":"Thyme","rarity":"common","id":"thyme","subtitle":"Herb","details":"Thymus vulgaris creeps happily in a small sunny pot and prefers its soil on the dry, lean side.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thymian%20%28Thymus%20vulgaris%29%2C%20Nationalpark%20Hohe%20Tauern.jpg?width=1024"},{"name":"Chives","rarity":"common","id":"chives","subtitle":"Herb","details":"Allium schoenoprasum snips back endlessly for garnish and tops itself with purple pompom blooms in spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Allium%20schoenoprasum%20%28Bieslook%29.%20actm.jpg?width=1024"},{"name":"Parsley","rarity":"common","id":"parsley","subtitle":"Herb","details":"Petroselinum crispum is slow to sprout but then yields curly or flat leaves for months of indoor picking.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Petroselinum%20crispum%202011.JPG?width=1024"},{"name":"Fungus Gnats","rarity":"common","id":"fungus-gnats","subtitle":"Pest","details":"Tiny black flies that dance over damp potting mix; their larvae feed in the soil while adults annoy everyone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Moucheron%20%282908093318%29.jpg?width=1024"},{"name":"Scale Insects","rarity":"common","id":"scale-insects","subtitle":"Pest","details":"Armoured bumps that look like part of the stem, scale insects sit motionless sipping sap for months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Icerya-purchasi.jpg?width=1024"},{"name":"Aphids","rarity":"common","id":"aphids","subtitle":"Pest","details":"Soft green sap-suckers that colonise tender new growth in days and coat leaves below in sticky honeydew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Starr-101129-9569-Senecio%20madagascariensis-flower%20stem%20with%20aphids-Piiholo-Maui%20%2824963851711%29.jpg?width=1024"},{"name":"Thrips","rarity":"common","id":"thrips","subtitle":"Pest","details":"Slender, barely-visible insects that rasp leaves silvery and scatter black specks across the undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frankliniella%20occidentalis%205364132-LGPT.jpg?width=1024"},{"name":"Whiteflies","rarity":"common","id":"whiteflies","subtitle":"Pest","details":"Brush an infested plant and a cloud of tiny white moth-like flies rises; they feast and breed on leaf undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Weisse-Fliege.jpg?width=1024"},{"name":"Leaf Cutting","rarity":"common","id":"leaf-cutting","subtitle":"Propagation","details":"A single leaf of snake plant or peperomia, set in mix or water, can grow roots and a whole new plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kalanchoe%20veg.jpg?width=1024"},{"name":"Stem Cutting","rarity":"common","id":"stem-cutting","subtitle":"Propagation","details":"Snip just below a node, strip the lower leaves and root the stem: the classic way to multiply most houseplants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Basilikum%20%28Ocimum%20basilicum%29%20Stecklinge%20--%20Josef%20Schlaghecken.jpg?width=1024"},{"name":"Pups and Offsets","rarity":"common","id":"pups-and-offsets","subtitle":"Propagation","details":"Many houseplants clone themselves as side babies; potted up once they have roots, each pup is a free plant.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SpiderPlantPlantlets.jpg?width=1024"},{"name":"Overwatering","rarity":"common","id":"overwatering","subtitle":"Care","details":"The most common houseplant killer: constant wet mix suffocates roots long before the leaves admit trouble.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chlorose%20ferrique%20sur%20Citrus%20aurantium.jpg?width=1024"},{"name":"Leggy Growth","rarity":"common","id":"leggy-growth","subtitle":"Care","details":"Etiolation: starved of light, stems stretch pale and spindly toward the window, reaching for a sun that isn't there.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Etiolation%20of%20plants.JPG?width=1024"},{"name":"Rotating for Even Growth","rarity":"common","id":"rotating-for-even-growth","subtitle":"Care","details":"Houseplants lean hard toward the glass; a quarter-turn at each watering keeps growth even on every side.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bright%20windowsill%20%28Unsplash%29.jpg?width=1024"},{"name":"Repotting","rarity":"common","id":"repotting","subtitle":"Care","details":"When roots circle the drainage hole, a pot one size up with fresh mix restarts a cramped plant's growth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/3%20freshly%20repotted%20plants.JPG?width=1024"},{"name":"Moisture Meter","rarity":"common","id":"moisture-meter","subtitle":"Tool","details":"A probe pushed deep into the mix reads the water the roots actually feel, ending the guesswork of watering day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soil%20moisture%20sensor.JPG?width=900"},{"name":"Pruning Shears","rarity":"common","id":"pruning-shears","subtitle":"Tool","details":"Clean, sharp snips remove dead leaves and leggy stems; cuts made just above a node invite bushier regrowth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/My%20trusty%20gardening%20gloves%20%26%20secateurs%20which%20need%20a%20good%20clean%20by%20the%20look%20of%20them%20%288711272274%29.jpg?width=1024"},{"name":"Macrame Hanger","rarity":"common","id":"macrame-hanger","subtitle":"Tool","details":"Knotted cord plant hangers lifted trailing plants into sunny windows in the 1970s and never really left.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Macrame%20Basic%20Knots.jpg?width=1024"},{"name":"Watering Can","rarity":"common","id":"watering-can","subtitle":"Tool","details":"A long, narrow spout threads between leaves to deliver water to the soil, not the foliage, of crowded shelves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Metal%20watering%20can.jpg?width=1024"}]});
